window.HOEREN = {"1":[{"id":"h1","type":"Radiobeitrag","title":"Wenn Großeltern zu Betreuern werden","title_fa":"وقتی پدربزرگ‌ها و مادربزرگ‌ها از نوه‌ها نگهداری می‌کنند","intro_fa":"یک گوینده در برنامه‌ای رادیویی دربارهٔ پدربزرگ‌ها و مادربزرگ‌هایی صحبت می‌کند که از نوه‌هایشان نگهداری می‌کنند.","s":[{"de":"Guten Morgen, liebe Hörerinnen und Hörer, heute geht es in unserer Sendung um Großeltern.","fa":"صبح بخیر، شنوندگان عزیز؛ امروز برنامهٔ ما دربارهٔ پدربزرگ‌ها و مادربزرگ‌هاست."},{"de":"In Deutschland kümmern sich viele Senioren regelmäßig um ihre Enkelkinder.","fa":"در آلمان بسیاری از سالمندان به‌طور منظم از نوه‌هایشان مراقبت می‌کنند."},{"de":"Laut einer Umfrage betreut fast jede zweite Großmutter mindestens einmal pro Woche ihre Enkel.","fa":"طبق یک نظرسنجی، تقریباً از هر دو مادربزرگ یکی دست‌کم هفته‌ای یک بار از نوه‌هایش نگهداری می‌کند."},{"de":"Das hilft vor allem Eltern, die beide berufstätig sind.","fa":"این کار به‌خصوص به والدینی کمک می‌کند که هر دو شاغل هستند."},{"de":"Helga Brandt aus Kassel ist 68 Jahre alt und holt dreimal pro Woche ihre Enkelin Mia vom Kindergarten ab.","fa":"هلگا برانت اهل کاسل ۶۸ سال دارد و هفته‌ای سه بار نوه‌اش، میا، را از مهدکودک می‌آورد."},{"de":"Sie erzählt, dass sie sich jedes Mal auf die Nachmittage mit Mia freut.","fa":"او تعریف می‌کند که هر بار مشتاق بعدازظهرهایی است که با میا می‌گذراند."},{"de":"Seit der Geburt ihrer Enkelin fühlt sie sich wieder jung, sagt sie.","fa":"به گفتهٔ خودش، از وقتی نوه‌اش به دنیا آمده، دوباره احساس جوانی می‌کند."},{"de":"Obwohl die Betreuung manchmal anstrengend ist, möchte sie diese Zeit auf keinen Fall verpassen.","fa":"با اینکه نگهداری از بچه گاهی خسته‌کننده است، او به هیچ وجه نمی‌خواهد این دوران را از دست بدهد."},{"de":"Doch nicht alle Großeltern sehen das so positiv.","fa":"اما همهٔ پدربزرگ‌ها و مادربزرگ‌ها این موضوع را این‌قدر مثبت نمی‌بینند."},{"de":"Manche ärgern sich darüber, dass die eigenen Kinder zu viel Hilfe erwarten.","fa":"بعضی از آن‌ها از اینکه فرزندانشان بیش از حد از آن‌ها انتظار کمک دارند، ناراحت می‌شوند."},{"de":"Sie haben lange gearbeitet und wünschen sich jetzt mehr Freiheit, zum Beispiel für Reisen oder Hobbys.","fa":"آن‌ها سال‌ها کار کرده‌اند و حالا آزادی بیشتری می‌خواهند، مثلاً برای سفر یا سرگرمی‌هایشان."},{"de":"Experten sagen deshalb, dass Familien offen über ihre Wünsche sprechen sollten.","fa":"به همین دلیل کارشناسان می‌گویند خانواده‌ها باید صادقانه دربارهٔ خواسته‌هایشان صحبت کنند."},{"de":"Wenn alle ehrlich sind, gibt es weniger Streit, und das Verhältnis bleibt gut.","fa":"وقتی همه صادق باشند، دعوا کمتر می‌شود و رابطه خوب می‌ماند."},{"de":"Außerdem profitieren auch die Kinder, weil sie von den Großeltern viel lernen.","fa":"علاوه بر این، بچه‌ها هم سود می‌برند، چون از پدربزرگ و مادربزرگ چیزهای زیادی یاد می‌گیرند."},{"de":"Sie hören Geschichten aus der Kindheit ihrer Eltern und erfahren manches Familiengeheimnis.","fa":"آن‌ها قصه‌هایی از کودکی پدر و مادرشان می‌شنوند و از بعضی رازهای خانوادگی باخبر می‌شوند."},{"de":"Und die Großeltern bleiben durch den Kontakt zu den Enkeln körperlich und geistig aktiv.","fa":"پدربزرگ‌ها و مادربزرگ‌ها هم با ارتباط با نوه‌ها از نظر جسمی و ذهنی فعال می‌مانند."},{"de":"Morgen sprechen wir in unserer Sendung über ein anderes Thema: Freundschaften im Alter.","fa":"فردا در برنامهٔ ما دربارهٔ موضوع دیگری صحبت می‌کنیم: دوستی در دوران سالمندی."}],"q":[{"q":"Wie oft betreut fast jede zweite Großmutter ihre Enkel?","opts":["mindestens einmal pro Woche","einmal im Monat","jeden Tag"],"a":0,"fa":"گوینده می‌گوید تقریباً از هر دو مادربزرگ یکی «دست‌کم هفته‌ای یک بار» از نوه‌هایش نگهداری می‌کند."},{"q":"Was macht Helga Brandt dreimal pro Woche?","opts":["Sie fährt mit Mia in den Urlaub.","Sie arbeitet in einem Kindergarten.","Sie holt Mia vom Kindergarten ab."],"a":2,"fa":"هلگا برانت هفته‌ای سه بار نوه‌اش را از مهدکودک می‌آورد."},{"q":"Wie fühlt sich Frau Brandt seit der Geburt ihrer Enkelin?","opts":["müde und alt","wieder jung","traurig"],"a":1,"fa":"او می‌گوید از زمان تولد نوه‌اش «دوباره احساس جوانی می‌کند»."},{"q":"Worüber ärgern sich manche Großeltern?","opts":["darüber, dass ihre Kinder zu viel Hilfe erwarten","über laute Kinder","über zu wenig Kontakt zu den Enkeln"],"a":0,"fa":"بعضی ناراحت‌اند که فرزندانشان بیش از حد از آن‌ها انتظار کمک دارند."},{"q":"Was empfehlen Experten?","opts":["Familien sollten offen über ihre Wünsche sprechen.","Eltern sollten weniger arbeiten.","Großeltern sollten jeden Tag helfen."],"a":0,"fa":"کارشناسان توصیه می‌کنند خانواده‌ها صادقانه دربارهٔ خواسته‌هایشان حرف بزنند."},{"q":"Worum geht es morgen in der Sendung?","opts":["um Reisen im Alter","um Kindergärten","um Freundschaften im Alter"],"a":2,"fa":"در پایان گفته می‌شود که موضوع برنامهٔ فردا «دوستی در دوران سالمندی» است."}]},{"id":"h2","type":"Sprachnachricht","title":"Lenas Sprachnachricht: Große Neuigkeiten","title_fa":"پیام صوتی لنا: یک خبر بزرگ","intro_fa":"لنا برای دوستش سارا پیام صوتی می‌گذارد تا خبر نامزدی خواهرش را بدهد و از او کمک بخواهد.","s":[{"de":"Hallo Sara, hier ist Lena, ich hoffe, es geht dir gut!","fa":"سلام سارا، لنا هستم، امیدوارم حالت خوب باشد!"},{"de":"Ich rufe an, weil ich dir unbedingt etwas erzählen muss.","fa":"زنگ می‌زنم چون حتماً باید چیزی برایت تعریف کنم."},{"de":"Meine Schwester Julia und ihr Freund Tom haben sich gestern verlobt!","fa":"خواهرم یولیا و دوست‌پسرش تام دیروز نامزد کردند!"},{"de":"Die Hochzeit soll schon im Juni stattfinden, und wir freuen uns alle riesig darauf.","fa":"قرار است عروسی همین ژوئن برگزار شود و همهٔ ما خیلی مشتاقش هستیم."},{"de":"Ehrlich gesagt war ich zuerst ein bisschen überrascht, denn die beiden kennen sich erst seit einem Jahr.","fa":"راستش اول کمی تعجب کردم، چون آن دو فقط یک سال است که همدیگر را می‌شناسند."},{"de":"Aber Tom ist ein ruhiger, freundlicher Mensch, und er passt wirklich gut zu Julia.","fa":"ولی تام آدم آرام و مهربانی است و واقعاً به یولیا می‌آید."},{"de":"Nur meine Mutter macht sich ein bisschen Sorgen, weil Julia erst 22 ist.","fa":"فقط مادرم کمی نگران است، چون یولیا تازه ۲۲ سالش است."},{"de":"Ich habe auch noch eine Bitte an dich.","fa":"یک خواهش هم از تو دارم."},{"de":"Julia möchte, dass ich ihre Trauzeugin werde, und ich bin furchtbar nervös.","fa":"یولیا می‌خواهد که من ساقدوشش باشم و من خیلی استرس دارم."},{"de":"Kannst du mir helfen, ein passendes Kleid zu finden?","fa":"می‌توانی کمکم کنی یک لباس مناسب پیدا کنم؟"},{"de":"Du hast so einen guten Geschmack, und ich habe keine Ahnung, was man auf einer Hochzeit trägt.","fa":"تو خیلی خوش‌سلیقه‌ای و من اصلاً نمی‌دانم آدم در عروسی چه می‌پوشد."},{"de":"Es sollte elegant sein, aber nicht zu teuer, weil ich gerade wenig Geld habe.","fa":"باید شیک باشد، ولی نه خیلی گران، چون الان پول زیادی ندارم."},{"de":"Wenn du Zeit hast, könnten wir am Samstagvormittag zusammen in die Stadt fahren.","fa":"اگر وقت داشته باشی، می‌توانیم شنبه صبح با هم به مرکز شهر برویم."},{"de":"Am Nachmittag geht es leider nicht, denn da besuche ich meine Großmutter im Seniorenheim.","fa":"بعدازظهر متأسفانه نمی‌شود، چون آن موقع به دیدن مادربزرگم در خانهٔ سالمندان می‌روم."},{"de":"Obwohl sie oft müde ist, freut sie sich immer sehr über Besuch.","fa":"با اینکه او اغلب خسته است، همیشه از اینکه کسی به دیدنش برود خیلی خوشحال می‌شود."},{"de":"Ruf mich doch bitte heute Abend zurück, dann können wir alles besprechen.","fa":"لطفاً امشب به من زنگ بزن تا بتوانیم دربارهٔ همه‌چیز صحبت کنیم."},{"de":"Bis später, ich umarme dich!","fa":"فعلاً خداحافظ، بغلت می‌کنم!"}],"q":[{"q":"Warum ruft Lena an?","opts":["Sie möchte Sara zum Geburtstag gratulieren.","Sie hat Probleme bei der Arbeit.","Sie hat eine Neuigkeit über ihre Schwester."],"a":2,"fa":"لنا زنگ می‌زند چون خواهرش یولیا نامزد کرده است."},{"q":"Warum war Lena zuerst überrascht?","opts":["Weil Julia und Tom sich erst seit einem Jahr kennen.","Weil Tom viel älter ist als Julia.","Weil die Hochzeit im Ausland stattfindet."],"a":0,"fa":"او می‌گوید آن دو «فقط یک سال است» که همدیگر را می‌شناسند."},{"q":"Warum macht sich die Mutter Sorgen?","opts":["Julia ist erst 22 Jahre alt.","Die Hochzeit ist zu teuer.","Sie mag Tom nicht."],"a":0,"fa":"مادر نگران است چون یولیا «تازه ۲۲ سال» دارد."},{"q":"Wobei soll Sara Lena helfen?","opts":["bei der Suche nach einem Kleid","bei der Organisation der Hochzeit","beim Kauf eines Hochzeitsgeschenks"],"a":0,"fa":"لنا می‌پرسد: «می‌توانی کمکم کنی یک لباس مناسب پیدا کنم؟»"},{"q":"Was macht Lena am Samstagnachmittag?","opts":["Sie geht mit Julia einkaufen.","Sie arbeitet.","Sie besucht ihre Großmutter."],"a":2,"fa":"شنبه بعدازظهر به دیدن مادربزرگش در خانهٔ سالمندان می‌رود."},{"q":"Wann soll Sara zurückrufen?","opts":["am Samstagvormittag","heute Abend","morgen früh"],"a":1,"fa":"لنا در پایان می‌گوید: «لطفاً امشب به من زنگ بزن.»"}]}],"10":[{"id":"h1","type":"Nachrichten","title":"Nachrichten aus unserer Stadt","title_fa":"اخبار شهر ما","intro_fa":"گوینده‌ی یک رادیوی محلی اخبار شهر را می‌خواند: تصمیم تازه‌ی شورای شهر، هشدار پلیس و یک خبر خوب.","s":[{"de":"Hier sind die Nachrichten aus unserer Stadt.","fa":"این‌ها اخبار شهر ما هستند."},{"de":"Der Stadtrat hat gestern Abend mit großer Mehrheit eine Reform der Parkgebühren beschlossen.","fa":"شورای شهر دیشب با اکثریت قاطع اصلاح هزینه‌های پارکینگ را تصویب کرد."},{"de":"Ab Januar kostet eine Stunde Parken in der Innenstadt drei Euro statt bisher einen Euro fünfzig.","fa":"از ژانویه یک ساعت پارک در مرکز شهر به جای یک یورو و پنجاه سنت فعلی، سه یورو هزینه دارد."},{"de":"Mit dem zusätzlichen Geld sollen öffentliche Busse und neue Radwege finanziert werden.","fa":"قرار است با این پول اضافی اتوبوس‌های عمومی و مسیرهای دوچرخه‌ی جدید تأمین مالی شوند."},{"de":"Viele Geschäftsleute sind mit der Entscheidung nicht einverstanden, deshalb haben sie für Samstag einen Protest angekündigt.","fa":"بسیاری از کاسب‌ها با این تصمیم موافق نیستند، به همین دلیل برای شنبه یک تجمع اعتراضی اعلام کرده‌اند."},{"de":"Sie fürchten, dass weniger Kunden in die Stadt kommen werden.","fa":"آن‌ها نگران‌اند که مشتری‌های کمتری به شهر بیایند."},{"de":"Die Bürgermeisterin hat trotzdem betont, dass die Reform wichtig für die Zukunft der Stadt ist.","fa":"با این حال شهردار تأکید کرد که این اصلاح برای آینده‌ی شهر مهم است."},{"de":"Außerdem lädt die Stadt alle Bürger am nächsten Mittwoch zu einer öffentlichen Versammlung ins Rathaus ein.","fa":"علاوه بر این، شهر همه‌ی شهروندان را چهارشنبه‌ی آینده به یک جلسه‌ی عمومی در ساختمان شهرداری دعوت می‌کند."},{"de":"Dort kann jeder seine Meinung sagen und Fragen stellen.","fa":"آنجا هر کسی می‌تواند نظرش را بگوید و سؤال بپرسد."},{"de":"Nun zu einer Meldung der Polizei.","fa":"حالا برویم سراغ خبری از پلیس."},{"de":"In den letzten Wochen haben Betrüger am Telefon vor allem ältere Menschen angerufen.","fa":"در هفته‌های اخیر کلاهبردارانی بیشتر به افراد مسن تلفن زده‌اند."},{"de":"Sie haben sich als Polizisten ausgegeben und nach Geld und Schmuck gefragt.","fa":"آن‌ها خودشان را پلیس معرفی کرده‌اند و دنبال پول و جواهرات بوده‌اند."},{"de":"Die Polizei warnt: Echte Polizisten fragen am Telefon nie nach Geld.","fa":"پلیس هشدار می‌دهد: پلیس واقعی هرگز پشت تلفن پول نمی‌خواهد."},{"de":"Legen Sie bei solchen Anrufen sofort auf, sonst verlieren Sie vielleicht viel Geld.","fa":"در چنین تماس‌هایی فوراً گوشی را بگذارید، وگرنه شاید پول زیادی از دست بدهید."},{"de":"Wer betrogen wurde, sollte den Fall sofort bei der Polizei anzeigen.","fa":"هر کس فریب خورده است، باید فوراً موضوع را به پلیس گزارش کند."},{"de":"Und zum Schluss eine gute Nachricht: Am Sonntag wird der neu gebaute Spielplatz im Stadtpark eröffnet.","fa":"و در پایان یک خبر خوب: یکشنبه زمین بازی تازه‌ساخته‌شده در پارک شهر افتتاح می‌شود."},{"de":"Zur Eröffnung gibt es ein kleines Fest mit Musik für die ganze Familie.","fa":"به مناسبت افتتاح، یک جشن کوچک با موسیقی برای همه‌ی خانواده برگزار می‌شود."}],"q":[{"q":"Was hat der Stadtrat beschlossen?","opts":["höhere Parkgebühren in der Innenstadt","eine neue Bürgermeisterin","ein Verbot von Radwegen"],"a":0,"fa":"شورای شهر اصلاح هزینه‌های پارکینگ را تصویب کرده و پارک گران‌تر می‌شود."},{"q":"Wie viel kostet eine Stunde Parken ab Januar?","opts":["fünf Euro","einen Euro fünfzig","drei Euro"],"a":2,"fa":"از ژانویه سه یورو؛ یک یورو و پنجاه سنت قیمت قبلی است."},{"q":"Warum sind viele Geschäftsleute gegen die Reform?","opts":["Sie wollen mehr Busse.","Sie fürchten, dass weniger Kunden kommen.","Sie haben Angst vor Betrügern."],"a":1,"fa":"کاسب‌ها نگران‌اند که مشتری‌های کمتری به شهر بیایند."},{"q":"Was findet am nächsten Mittwoch statt?","opts":["die Eröffnung des Spielplatzes","ein Protest der Geschäftsleute","eine öffentliche Versammlung im Rathaus"],"a":2,"fa":"چهارشنبه جلسه‌ی عمومی در شهرداری است؛ اعتراض شنبه و افتتاح زمین بازی یکشنبه است."},{"q":"Was soll man tun, wenn ein falscher Polizist anruft?","opts":["das Geld schnell überweisen","die eigene Adresse nennen","sofort auflegen"],"a":2,"fa":"پلیس توصیه می‌کند در چنین تماس‌هایی فوراً گوشی را بگذارید."},{"q":"Was wird am Sonntag eröffnet?","opts":["ein neuer Radweg","ein neues Rathaus","ein neu gebauter Spielplatz"],"a":2,"fa":"یکشنبه زمین بازی تازه‌ساخته‌شده در پارک شهر افتتاح می‌شود."}]},{"id":"h2","type":"Erfahrungsbericht","title":"Mein Weg in Deutschland","title_fa":"مسیر من در آلمان","intro_fa":"امیر، مردی اهل شیراز، در جشن یک انجمن کمک به ادغام مهاجران از تجربه‌های خود در چهار سال زندگی در آلمان می‌گوید.","s":[{"de":"Guten Abend, liebe Gäste, ich freue mich, dass ich heute hier sprechen darf.","fa":"عصر بخیر، مهمانان عزیز، خوشحالم که امروز اینجا می‌توانم صحبت کنم."},{"de":"Mein Name ist Amir, ich komme aus Schiras im Iran und lebe seit vier Jahren in Deutschland.","fa":"اسم من امیر است، اهل شیراز در ایران هستم و چهار سال است که در آلمان زندگی می‌کنم."},{"de":"Am Anfang war alles sehr schwer für mich, denn ich konnte kaum Deutsch.","fa":"اولش همه‌چیز برایم خیلی سخت بود، چون تقریباً آلمانی بلد نبودم."},{"de":"Die geschriebenen Briefe vom Amt habe ich überhaupt nicht verstanden, deshalb hatte ich oft Angst vor dem Briefkasten.","fa":"نامه‌های نوشته‌شده‌ی اداره را اصلاً نمی‌فهمیدم، به همین دلیل اغلب از صندوق پست می‌ترسیدم."},{"de":"Trotzdem habe ich nicht aufgegeben und jeden Tag einen Deutschkurs besucht.","fa":"با این حال تسلیم نشدم و هر روز در کلاس آلمانی شرکت کردم."},{"de":"Außerdem habe ich mich als Freiwilliger in einem Sportverein engagiert.","fa":"علاوه بر این، به‌عنوان داوطلب در یک باشگاه ورزشی فعالیت کردم."},{"de":"Dort habe ich nicht nur Fußball gespielt, sondern vor allem viele nette Menschen kennengelernt.","fa":"آنجا نه‌تنها فوتبال بازی کردم، بلکه مهم‌تر از همه با آدم‌های مهربان زیادی آشنا شدم."},{"de":"Ein älterer Nachbar hat mir dann geholfen, die vielen Formulare auszufüllen.","fa":"بعد یک همسایه‌ی مسن به من کمک کرد تا فرم‌های زیاد را پر کنم."},{"de":"Von ihm habe ich gelernt, dass man in Deutschland seine Meinung offen sagen darf, auch wenn andere nicht zustimmen.","fa":"از او یاد گرفتم که در آلمان می‌شود نظرت را آزادانه بگویی، حتی اگر دیگران موافق نباشند."},{"de":"Das war für mich zuerst ungewohnt, aber heute finde ich diese offene Diskussion sehr wertvoll.","fa":"این اولش برایم غیرعادی بود، اما امروز این گفت‌وگوی باز را خیلی ارزشمند می‌دانم."},{"de":"Natürlich gab es auch schwierige Erfahrungen, zum Beispiel bei der Wohnungssuche.","fa":"البته تجربه‌های سختی هم داشتم، مثلاً در پیدا کردن خانه."},{"de":"Manche Vermieter haben mich wegen meines Namens nicht eingeladen.","fa":"بعضی صاحب‌خانه‌ها به خاطر اسمم مرا برای دیدن خانه دعوت نکردند."},{"de":"In solchen Situationen muss man geduldig bleiben, sonst verliert man schnell die Hoffnung.","fa":"در چنین موقعیت‌هایی باید صبور بود، وگرنه آدم زود ناامید می‌شود."},{"de":"Letztes Jahr habe ich meine Ausbildung als Elektriker abgeschlossen, und jetzt arbeite ich in einer Firma hier.","fa":"پارسال دوره‌ی آموزش حرفه‌ای برق‌کاری‌ام را تمام کردم و حالا همین‌جا در یک شرکت کار می‌کنم."},{"de":"Nächstes Jahr möchte ich die Einbürgerung beantragen, dann darf ich auch bei Wahlen meine Stimme abgeben.","fa":"سال آینده می‌خواهم درخواست تابعیت بدهم، آن وقت می‌توانم در انتخابات هم رأی بدهم."},{"de":"Allen neu angekommenen Menschen möchte ich sagen: Sprechen Sie mit Ihren Nachbarn und haben Sie Mut!","fa":"به همه‌ی تازه‌واردها می‌خواهم بگویم: با همسایه‌هایتان حرف بزنید و شجاع باشید!"},{"de":"Vielen Dank für Ihre Aufmerksamkeit.","fa":"از توجه شما بسیار سپاسگزارم."}],"q":[{"q":"Wie lange lebt Amir schon in Deutschland?","opts":["seit zehn Jahren","seit vier Jahren","seit zwei Jahren"],"a":1,"fa":"امیر می‌گوید چهار سال است که در آلمان زندگی می‌کند."},{"q":"Warum hatte Amir am Anfang oft Angst vor dem Briefkasten?","opts":["Weil er die Briefe vom Amt nicht verstanden hat.","Weil er viele Rechnungen bekommen hat.","Weil sein Nachbar unfreundlich war."],"a":0,"fa":"او نامه‌های اداره را اصلاً نمی‌فهمید و به همین دلیل از صندوق پست می‌ترسید."},{"q":"Wo hat Amir viele nette Menschen kennengelernt?","opts":["im Deutschkurs","im Sportverein","bei der Arbeit"],"a":1,"fa":"در باشگاه ورزشی، جایی که داوطلب بود، با آدم‌های مهربان زیادی آشنا شد."},{"q":"Was hat Amir von seinem Nachbarn gelernt?","opts":["dass man anderen immer zustimmen sollte","wie man Fußball spielt","dass man seine Meinung offen sagen darf"],"a":2,"fa":"او از همسایه یاد گرفت که در آلمان می‌شود نظرت را آزادانه بگویی، حتی اگر دیگران موافق نباشند."},{"q":"Welches Problem hatte Amir bei der Wohnungssuche?","opts":["Manche Vermieter haben ihn wegen seines Namens nicht eingeladen.","Es gab keine freien Wohnungen.","Die Wohnungen waren zu teuer."],"a":0,"fa":"بعضی صاحب‌خانه‌ها به خاطر اسمش او را دعوت نکردند."},{"q":"Was möchte Amir nächstes Jahr machen?","opts":["eine Ausbildung beginnen","die Einbürgerung beantragen","zurück in den Iran gehen"],"a":1,"fa":"او می‌خواهد سال آینده درخواست تابعیت بدهد؛ دوره‌ی آموزش حرفه‌ای را پارسال تمام کرده است."}]}],"2":[{"id":"h1","type":"Führung","title":"Rundgang durch das Mehrgenerationenhaus","title_fa":"بازدید از یک خانهٔ چندنسلی","intro_fa":"یک راهنما گروهی از بازدیدکنندگان را در یک خانهٔ چندنسلی می‌گرداند و زندگی مشترک ساکنان آن را توضیح می‌دهد.","s":[{"de":"Herzlich willkommen im Lindenhof, schön, dass Sie heute an unserer Führung teilnehmen!","fa":"به لیندن‌هوف خوش آمدید؛ خوشحالم که امروز در بازدید ما شرکت می‌کنید!"},{"de":"Der Lindenhof ist ein Mehrgenerationenhaus, in dem junge Familien, Studenten und Senioren zusammenleben.","fa":"لیندن‌هوف یک خانهٔ چندنسلی است که در آن خانواده‌های جوان، دانشجوها و سالمندان با هم زندگی می‌کنند."},{"de":"Das Gebäude, das Sie hier vor sich sehen, war früher eine Schule.","fa":"ساختمانی که اینجا روبه‌رویتان می‌بینید، قبلاً یک مدرسه بود."},{"de":"Vor zehn Jahren hat die Stadt es umgebaut, und heute gibt es hier 24 Wohnungen.","fa":"ده سال پیش شهرداری آن را بازسازی کرد و امروز اینجا ۲۴ واحد مسکونی وجود دارد."},{"de":"Die kleinsten Apartments haben nur 30 Quadratmeter, die größten Wohnungen haben vier Zimmer.","fa":"کوچک‌ترین آپارتمان‌ها فقط ۳۰ متر مربع هستند و بزرگ‌ترین واحدها چهار اتاق دارند."},{"de":"Wir gehen jetzt in den Hof, wo die Kinder nach der Schule spielen.","fa":"حالا به حیاط می‌رویم، جایی که بچه‌ها بعد از مدرسه بازی می‌کنند."},{"de":"Den Rasen und die Beete pflegen die Bewohner gemeinsam, jeder hat einmal im Monat Gartendienst.","fa":"ساکنان با هم از چمن و باغچه‌ها مراقبت می‌کنند؛ هر کس ماهی یک بار نوبت باغبانی دارد."},{"de":"Hier rechts sehen Sie die Gemeinschaftsküche, in der wir jeden Freitag zusammen kochen.","fa":"اینجا سمت راست آشپزخانهٔ مشترک را می‌بینید که هر جمعه در آن با هم آشپزی می‌کنیم."},{"de":"Die Möbel, die hier stehen, haben uns Nachbarn aus dem Viertel geschenkt.","fa":"مبلمانی را که اینجا هست، همسایه‌هایی از همین محله به ما هدیه داده‌اند."},{"de":"Auf dem großen Tisch liegen Listen, auf denen man sich für Aufgaben eintragen kann.","fa":"روی میز بزرگ فهرست‌هایی هست که می‌شود در آن‌ها برای کارهای مختلف اسم نوشت."},{"de":"Wer zum Beispiel Hilfe beim Einkaufen braucht, schreibt seinen Namen auf diese Liste.","fa":"مثلاً هر کس برای خرید کردن به کمک نیاز دارد، اسمش را روی این فهرست می‌نویسد."},{"de":"Unsere älteste Bewohnerin ist 91 Jahre alt und erzählt den Kindern gern Geschichten.","fa":"مسن‌ترین ساکن ما ۹۱ سال دارد و دوست دارد برای بچه‌ها قصه تعریف کند."},{"de":"Dafür helfen ihr die Studenten, wenn sie Probleme mit dem Handy oder der Fernbedienung hat.","fa":"در عوض، وقتی با موبایل یا کنترل تلویزیون مشکل دارد، دانشجوها به او کمک می‌کنند."},{"de":"Natürlich gibt es manchmal auch Streit, zum Beispiel wegen Lärm im Treppenhaus.","fa":"البته گاهی دعوا هم پیش می‌آید، مثلاً به خاطر سر و صدا در راه‌پله."},{"de":"Dann treffen sich alle Mieter zu einer Versammlung, bei der man gemeinsam eine Lösung sucht.","fa":"آن وقت همهٔ مستأجرها در جلسه‌ای جمع می‌شوند که در آن با هم دنبال راه‌حل می‌گردند."},{"de":"Die Lage ist übrigens ideal, denn bis zum Zentrum fährt man mit dem Bus nur zehn Minuten.","fa":"راستی موقعیت اینجا عالی است، چون با اتوبوس فقط ده دقیقه تا مرکز شهر راه است."},{"de":"Jetzt zeige ich Ihnen noch eine Wohnung, die gerade frei ist.","fa":"حالا یک آپارتمان را هم که الان خالی است نشانتان می‌دهم."}],"q":[{"q":"Was war das Gebäude früher?","opts":["eine Schule","eine Fabrik","ein Krankenhaus"],"a":0,"fa":"راهنما می‌گوید ساختمان «قبلاً یک مدرسه بود»."},{"q":"Wie viele Wohnungen gibt es heute im Lindenhof?","opts":["24","30","91"],"a":0,"fa":"امروز در لیندن‌هوف ۲۴ واحد مسکونی هست؛ ۳۰ متراژ کوچک‌ترین آپارتمان و ۹۱ سنِ مسن‌ترین ساکن است."},{"q":"Was passiert jeden Freitag in der Gemeinschaftsküche?","opts":["Die Bewohner kochen zusammen.","Es gibt einen Kochkurs für Kinder.","Die Küche wird geputzt."],"a":0,"fa":"راهنما می‌گوید هر جمعه در آشپزخانهٔ مشترک با هم آشپزی می‌کنند."},{"q":"Woher kommen die Möbel in der Küche?","opts":["aus einem Möbelgeschäft","aus der alten Schule","von Nachbarn aus dem Viertel"],"a":2,"fa":"مبلمان را همسایه‌هایی از همان محله هدیه داده‌اند."},{"q":"Wobei helfen die Studenten der ältesten Bewohnerin?","opts":["im Garten","bei Problemen mit dem Handy oder der Fernbedienung","beim Kochen"],"a":1,"fa":"دانشجوها وقتی او با موبایل یا کنترل تلویزیون مشکل دارد کمکش می‌کنند."},{"q":"Was machen die Mieter, wenn es Streit gibt?","opts":["Sie treffen sich zu einer Versammlung.","Sie ziehen aus.","Sie rufen die Polizei."],"a":0,"fa":"در صورت دعوا، همهٔ مستأجرها در یک جلسه جمع می‌شوند و دنبال راه‌حل می‌گردند."}]},{"id":"h2","type":"Sprachnachricht","title":"Sprachnachricht von Jonas: Tipps für die Wohnung","title_fa":"پیام صوتی یوناس: نکته‌هایی دربارهٔ آپارتمان","intro_fa":"یوناس که به سفر رفته، برای دوستش علی پیام می‌گذارد و توضیح می‌دهد وسایل خانه کجاست و علی چه کارهایی باید بکند.","s":[{"de":"Hallo Ali, hier ist Jonas, ich sitze schon im Zug nach Hamburg.","fa":"سلام علی، یوناس هستم؛ الان در قطار هامبورگ نشسته‌ام."},{"de":"Vielen Dank noch einmal, dass du dich zwei Wochen um meine Wohnung kümmerst!","fa":"باز هم خیلی ممنون که دو هفته به آپارتمانم رسیدگی می‌کنی!"},{"de":"Ich erkläre dir kurz, wo alles ist.","fa":"کوتاه برایت توضیح می‌دهم که هر چیزی کجاست."},{"de":"Den Schlüssel habe ich unter die Fußmatte vor der Tür gelegt.","fa":"کلید را زیر پادری جلوی در گذاشته‌ام."},{"de":"Die Pflanzen stehen im Wohnzimmer auf der Fensterbank und brauchen jeden zweiten Tag Wasser.","fa":"گلدان‌ها در اتاق نشیمن روی لبهٔ پنجره هستند و یک روز در میان آب لازم دارند."},{"de":"Die Gießkanne steht im Bad neben der Badewanne.","fa":"آب‌پاش در حمام کنار وان است."},{"de":"Wenn du fernsehen willst: Die Fernbedienung liegt meistens zwischen den Kissen auf der Couch.","fa":"اگر خواستی تلویزیون ببینی، کنترل معمولاً لای کوسن‌های روی کاناپه است."},{"de":"Saubere Handtücher findest du im Schrank im Schlafzimmer, ganz oben.","fa":"حوله‌های تمیز را در کمد اتاق خواب، در طبقهٔ بالای آن پیدا می‌کنی."},{"de":"Bitte stell den Müll am Mittwochabend vor das Haus, denn am Donnerstag wird er abgeholt.","fa":"لطفاً چهارشنبه شب زباله را جلوی خانه بگذار، چون پنجشنبه آن را می‌برند."},{"de":"Meine Post kannst du einfach auf den Schreibtisch legen.","fa":"نامه‌هایم را می‌توانی همین‌طوری روی میز تحریر بگذاری."},{"de":"Ach ja, im Flur hängt ein Zettel mit der Telefonnummer von Frau Keller.","fa":"آهان راستی، در راهرو یک کاغذ با شمارهٔ تلفن خانم کلر آویزان است."},{"de":"Sie ist die Nachbarin, die direkt unter mir wohnt, und sie ist sehr nett.","fa":"او همسایه‌ای است که درست طبقهٔ پایین من زندگی می‌کند و خیلی مهربان است."},{"de":"Wenn die Heizung nicht funktioniert, kannst du bei ihr klingeln.","fa":"اگر شوفاژ کار نکرد، می‌توانی زنگ خانه‌اش را بزنی."},{"de":"Sie hat auch einen zweiten Schlüssel, falls du deinen mal vergisst.","fa":"یک کلید دوم هم پیش اوست، اگر یک وقت کلیدت را جا گذاشتی."},{"de":"Im Kühlschrank liegen noch Käse und Gemüse, die musst du bitte essen, bevor sie schlecht werden.","fa":"در یخچال هنوز پنیر و سبزیجات هست؛ لطفاً قبل از اینکه خراب شوند، آن‌ها را بخور."},{"de":"Wenn etwas ist, schreib mir einfach eine Nachricht.","fa":"اگر مشکلی پیش آمد، کافی است برایم پیام بفرستی."},{"de":"Mach es gut und fühl dich wie zu Hause!","fa":"مواظب خودت باش و راحت باش، مثل خانهٔ خودت!"}],"q":[{"q":"Wo hat Jonas den Schlüssel hingelegt?","opts":["auf den Schreibtisch","in den Briefkasten","unter die Fußmatte vor der Tür"],"a":2,"fa":"یوناس می‌گوید کلید را «زیر پادری جلوی در» گذاشته است."},{"q":"Wie oft brauchen die Pflanzen Wasser?","opts":["einmal pro Woche","jeden Tag","jeden zweiten Tag"],"a":2,"fa":"گلدان‌ها یک روز در میان آب لازم دارند."},{"q":"Wo liegt die Fernbedienung meistens?","opts":["im Schlafzimmer","neben dem Fernseher","zwischen den Kissen auf der Couch"],"a":2,"fa":"کنترل تلویزیون معمولاً لای کوسن‌های روی کاناپه است."},{"q":"Wann soll Ali den Müll vor das Haus stellen?","opts":["am Wochenende","am Mittwochabend","am Donnerstagmorgen"],"a":1,"fa":"علی باید چهارشنبه شب زباله را جلوی خانه بگذارد، چون پنجشنبه آن را می‌برند."},{"q":"Wer ist Frau Keller?","opts":["die Tante von Jonas","die Nachbarin, die unter Jonas wohnt","die Vermieterin von Jonas"],"a":1,"fa":"خانم کلر همسایه‌ای است که درست طبقهٔ پایین یوناس زندگی می‌کند."},{"q":"Was soll Ali mit dem Käse und dem Gemüse machen?","opts":["Er soll sie Frau Keller geben.","Er soll sie essen.","Er soll sie wegwerfen."],"a":1,"fa":"یوناس می‌گوید پنیر و سبزیجات را قبل از اینکه خراب شوند بخورد."}]}],"3":[{"id":"h1","type":"Erfahrungsbericht","title":"Mein Weg zur ersten Stelle in Deutschland","title_fa":"مسیر من تا اولین شغلم در آلمان","intro_fa":"رضا، مهندس عمران ایرانی، در یک جلسهٔ اطلاع‌رسانی تجربهٔ خودش از پیدا کردن کار در آلمان را تعریف می‌کند.","s":[{"de":"Mein Name ist Reza, ich bin 34 Jahre alt und arbeite seit zwei Jahren als Bauingenieur in Stuttgart.","fa":"اسم من رضاست، ۳۴ سال دارم و دو سال است که در اشتوتگارت مهندس عمران هستم."},{"de":"Bevor ich nach Deutschland kam, hatte ich schon sechs Jahre in Schiras gearbeitet.","fa":"قبل از اینکه به آلمان بیایم، شش سال در شیراز کار کرده بودم."},{"de":"Ich war damals Leiter eines kleinen Teams und plante Wohngebäude.","fa":"آن موقع سرپرست یک تیم کوچک بودم و ساختمان‌های مسکونی طراحی می‌کردم."},{"de":"Als ich in Deutschland ankam, sprach ich leider nur wenig Deutsch.","fa":"وقتی به آلمان رسیدم، متأسفانه فقط کمی آلمانی بلد بودم."},{"de":"Deshalb besuchte ich zuerst ein Jahr lang einen Intensivkurs.","fa":"برای همین اول یک سال در یک دورهٔ فشردهٔ زبان شرکت کردم."},{"de":"Nachdem ich meine Deutschprüfung bestanden hatte, ließ ich mein Diplom anerkennen.","fa":"بعد از اینکه امتحان آلمانی‌ام را قبول شدم، برای تأیید مدرک دانشگاهی‌ام اقدام کردم."},{"de":"Das dauerte fast vier Monate, und ich musste viele Dokumente übersetzen lassen.","fa":"این کار تقریباً چهار ماه طول کشید و مجبور شدم مدارک زیادی را برای ترجمه بدهم."},{"de":"Danach schrieb ich mehr als 40 Bewerbungen, aber zuerst bekam ich nur Absagen.","fa":"بعد از آن بیش از ۴۰ درخواست کار فرستادم، اما اولش فقط جواب منفی گرفتم."},{"de":"Das war eine schwierige Zeit, denn ich zweifelte oft an meinen Fähigkeiten.","fa":"دوران سختی بود، چون اغلب به توانایی‌هایم شک می‌کردم."},{"de":"Eine Beraterin von der Arbeitsagentur gab mir dann einen wichtigen Tipp.","fa":"بعد یک مشاور از ادارهٔ کار توصیهٔ مهمی به من کرد."},{"de":"Sie empfahl mir, zuerst ein Praktikum zu machen, um Erfahrung in einer deutschen Firma zu sammeln.","fa":"او پیشنهاد کرد اول یک دورهٔ کارآموزی بگذرانم تا در یک شرکت آلمانی تجربه کسب کنم."},{"de":"Während des Praktikums lernte ich die deutschen Normen und viele Fachwörter kennen.","fa":"در طول کارآموزی با استانداردهای آلمانی و اصطلاحات تخصصی زیادی آشنا شدم."},{"de":"Mein Chef war mit meiner Arbeit sehr zufrieden.","fa":"رئیسم از کارم خیلی راضی بود."},{"de":"Sobald das Praktikum zu Ende war, bot er mir einen Arbeitsvertrag an.","fa":"به محض اینکه کارآموزی تمام شد، به من قرارداد کاری پیشنهاد داد."},{"de":"Heute arbeite ich in Vollzeit und betreue eigene Aufträge.","fa":"امروز تمام‌وقت کار می‌کنم و مسئول پروژه‌های خودم هستم."},{"de":"Im nächsten Jahr möchte ich eine Fortbildung machen, damit ich Projektleiter werden kann.","fa":"سال آینده می‌خواهم یک دورهٔ آموزشی تکمیلی بگذرانم تا بتوانم مدیر پروژه شوم."},{"de":"Allen, die gerade eine Stelle suchen, möchte ich sagen: Geben Sie nicht auf!","fa":"به همهٔ کسانی که الان دنبال کار هستند می‌خواهم بگویم: ناامید نشوید!"}],"q":[{"q":"Wie lange arbeitet Reza schon in Stuttgart?","opts":["seit vier Monaten","seit zwei Jahren","seit sechs Jahren"],"a":1,"fa":"رضا می‌گوید «دو سال است» که در اشتوتگارت کار می‌کند؛ شش سال مربوط به کارش در شیراز است."},{"q":"Was machte Reza zuerst in Deutschland?","opts":["Er besuchte einen Intensivkurs.","Er arbeitete als Teamleiter.","Er machte ein Praktikum."],"a":0,"fa":"او چون آلمانی کمی بلد بود، اول یک سال در دورهٔ فشردهٔ زبان شرکت کرد."},{"q":"Wie viele Bewerbungen schrieb Reza?","opts":["genau 6","etwa 10","mehr als 40"],"a":2,"fa":"او می‌گوید بیش از ۴۰ درخواست کار فرستاده است."},{"q":"Was empfahl ihm die Beraterin?","opts":["eine neue Ausbildung zu machen","zuerst ein Praktikum zu machen","in eine andere Stadt zu ziehen"],"a":1,"fa":"مشاور ادارهٔ کار پیشنهاد داد اول کارآموزی کند."},{"q":"Was passierte nach dem Praktikum?","opts":["Reza wurde selbstständig.","Der Chef bot ihm einen Vertrag an.","Reza ging zurück in den Iran."],"a":1,"fa":"به محض تمام شدن کارآموزی، رئیس به او قرارداد کاری پیشنهاد داد."},{"q":"Warum möchte Reza eine Fortbildung machen?","opts":["weil er mehr Freizeit möchte","weil er sein Diplom verloren hat","damit er Projektleiter werden kann"],"a":2,"fa":"او می‌خواهد دورهٔ تکمیلی بگذراند «تا بتواند مدیر پروژه شود»."}]},{"id":"h2","type":"Radiobeitrag","title":"Vier Tage arbeiten, drei Tage frei?","title_fa":"چهار روز کار، سه روز تعطیلی؟","intro_fa":"یک گزارشگر رادیو دربارهٔ هفتهٔ کاری چهارروزه، آزمایش یک شرکت و مزایا و معایب آن گزارش می‌دهد.","s":[{"de":"Immer mehr Beschäftigte in Deutschland wünschen sich eine Vier-Tage-Woche.","fa":"شاغلان بیشتر و بیشتری در آلمان آرزوی هفتهٔ کاری چهارروزه را دارند."},{"de":"In einer Umfrage sagten 73 Prozent der Befragten, dass sie gern nur vier Tage pro Woche arbeiten würden.","fa":"در یک نظرسنجی، ۷۳ درصد از شرکت‌کنندگان گفتند که دوست دارند فقط چهار روز در هفته کار کنند."},{"de":"Viele möchten dafür aber nicht weniger Geld verdienen.","fa":"اما بسیاری نمی‌خواهند به خاطر آن درآمد کمتری داشته باشند."},{"de":"Ein Softwareunternehmen aus Leipzig testete das Modell im letzten Jahr sechs Monate lang.","fa":"یک شرکت نرم‌افزاری در لایپزیگ سال گذشته این مدل را شش ماه آزمایش کرد."},{"de":"Die 60 Angestellten arbeiteten nur noch von Montag bis Donnerstag, bekamen aber das gleiche Gehalt.","fa":"۶۰ کارمند این شرکت فقط از دوشنبه تا پنجشنبه کار می‌کردند، اما همان حقوق را می‌گرفتند."},{"de":"Bevor der Test begann, hatte der Chef große Zweifel.","fa":"قبل از شروع آزمایش، رئیس شرکت تردید زیادی داشت."},{"de":"Er hatte Angst, dass die Firma ihre Aufträge nicht rechtzeitig schaffen würde.","fa":"او می‌ترسید که شرکت نتواند سفارش‌هایش را به موقع انجام دهد."},{"de":"Doch das Ergebnis war positiv: Die Mitarbeiter waren seltener krank und arbeiteten konzentrierter.","fa":"اما نتیجه مثبت بود: کارکنان کمتر بیمار می‌شدند و با تمرکز بیشتری کار می‌کردند."},{"de":"Außerdem wurden die Besprechungen kürzer, weil alle ihre Zeit besser planten.","fa":"علاوه بر این، جلسه‌ها کوتاه‌تر شدند، چون همه وقتشان را بهتر برنامه‌ریزی می‌کردند."},{"de":"Seit dem Ende des Tests arbeitet die Firma weiter nach diesem Modell.","fa":"از پایان آزمایش، شرکت همچنان با همین مدل کار می‌کند."},{"de":"Nicht alle Experten sind jedoch so begeistert.","fa":"با این حال همهٔ کارشناسان این‌قدر مشتاق نیستند."},{"de":"In Krankenhäusern oder Geschäften ist eine Vier-Tage-Woche schwer zu organisieren, weil immer jemand da sein muss.","fa":"در بیمارستان‌ها یا فروشگاه‌ها اجرای هفتهٔ چهارروزه سخت است، چون همیشه باید کسی آنجا باشد."},{"de":"Dort müssten die Betriebe mehr Personal einstellen, und das ist teuer.","fa":"آنجا شرکت‌ها مجبور می‌شدند نیروی بیشتری استخدام کنند و این گران است."},{"de":"Kritiker sagen außerdem, dass zehn Stunden Arbeit an einem Tag sehr anstrengend sein können.","fa":"منتقدان همچنین می‌گویند که ده ساعت کار در یک روز می‌تواند خیلی خسته‌کننده باشد."},{"de":"Für Eltern kann das Modell trotzdem ein großer Vorteil sein, weil sie mehr Zeit für die Familie haben.","fa":"با این حال این مدل می‌تواند برای والدین مزیت بزرگی باشد، چون وقت بیشتری برای خانواده دارند."},{"de":"Ob die Vier-Tage-Woche bald normal wird, ist noch offen.","fa":"اینکه هفتهٔ چهارروزه به زودی عادی شود یا نه، هنوز معلوم نیست."},{"de":"Was meinen Sie dazu, liebe Hörerinnen und Hörer?","fa":"شنوندگان عزیز، نظر شما در این باره چیست؟"},{"de":"Schreiben Sie uns eine Nachricht auf unserer Webseite.","fa":"در وب‌سایت ما برایمان پیام بنویسید."}],"q":[{"q":"Wie viele Befragte möchten gern nur vier Tage pro Woche arbeiten?","opts":["73 Prozent","37 Prozent","60 Prozent"],"a":0,"fa":"گزارشگر می‌گوید ۷۳ درصد از شرکت‌کنندگان در نظرسنجی چنین خواسته‌ای دارند."},{"q":"Wie lange testete die Firma aus Leipzig das Modell?","opts":["vier Wochen","sechs Monate","ein Jahr"],"a":1,"fa":"شرکت لایپزیگی این مدل را «شش ماه» آزمایش کرد."},{"q":"Wovor hatte der Chef vor dem Test Angst?","opts":["dass die Kunden sich beschweren","dass die Firma ihre Aufträge nicht rechtzeitig schafft","dass die Mitarbeiter kündigen"],"a":1,"fa":"رئیس می‌ترسید شرکت نتواند سفارش‌ها را به موقع انجام دهد."},{"q":"Was war ein Ergebnis des Tests?","opts":["Die Besprechungen wurden länger.","Die Mitarbeiter waren seltener krank.","Die Mitarbeiter verdienten mehr Geld."],"a":1,"fa":"نتیجه این بود که کارکنان کمتر بیمار شدند و جلسه‌ها کوتاه‌تر شد."},{"q":"Warum ist das Modell in Krankenhäusern schwierig?","opts":["weil die Krankenhäuser zu klein sind","weil die Ärzte es nicht wollen","weil immer jemand da sein muss"],"a":2,"fa":"گزارشگر می‌گوید در بیمارستان‌ها همیشه باید کسی حاضر باشد."},{"q":"Für wen kann das Modell ein großer Vorteil sein?","opts":["für Rentner","für Studenten","für Eltern"],"a":2,"fa":"این مدل برای والدین مزیت بزرگی است، چون وقت بیشتری برای خانواده دارند."}]}],"4":[{"id":"h1","type":"Kurzvortrag","title":"Wie lernt man neue Wörter am besten?","title_fa":"بهترین روش یادگیری واژه‌های جدید چیست؟","intro_fa":"یک معلم زبان در کلاس آلمانی سخنرانی کوتاهی دربارهٔ روش‌های یادگیری واژه ارائه می‌دهد.","s":[{"de":"Liebe Kursteilnehmerinnen und Kursteilnehmer, in meinem kurzen Vortrag geht es heute um das Thema Wortschatz.","fa":"شرکت‌کنندگان عزیز دوره، سخنرانی کوتاه امروز من دربارهٔ موضوع واژگان است."},{"de":"Viele Lernende haben das Problem, neue Wörter schnell wieder zu vergessen.","fa":"بسیاری از زبان‌آموزان این مشکل را دارند که واژه‌های جدید را زود فراموش می‌کنند."},{"de":"Forscher haben herausgefunden, dass wir ohne Wiederholung schon nach einer Woche etwa 70 Prozent vergessen.","fa":"پژوهشگران دریافته‌اند که ما بدون تکرار، فقط بعد از یک هفته حدود ۷۰ درصد را فراموش می‌کنیم."},{"de":"Deshalb ist es wichtig, neue Wörter regelmäßig zu wiederholen.","fa":"به همین دلیل مهم است که واژه‌های جدید را به طور منظم تکرار کنیم."},{"de":"Am besten wiederholen Sie ein Wort nach einem Tag, nach drei Tagen und dann nach einer Woche.","fa":"بهتر است یک واژه را بعد از یک روز، بعد از سه روز و سپس بعد از یک هفته تکرار کنید."},{"de":"Lernen Sie Nomen immer mit dem Artikel und dem Plural, damit Sie später keine Fehler machen.","fa":"اسم‌ها را همیشه با حرف تعریف و شکل جمعشان یاد بگیرید تا بعداً اشتباه نکنید."},{"de":"Viele schreiben die Wörter auf kleine Karteikarten, um sie überall dabeizuhaben.","fa":"خیلی‌ها واژه‌ها را روی کارت‌های کوچک می‌نویسند تا همه جا همراهشان باشد."},{"de":"Andere benutzen lieber eine App auf dem Handy.","fa":"بعضی دیگر ترجیح می‌دهند از یک اپلیکیشن روی موبایل استفاده کنند."},{"de":"Es hilft außerdem, Wörter nicht allein, sondern in einem Satz zu lernen.","fa":"علاوه بر این، کمک می‌کند که واژه‌ها را نه به تنهایی، بلکه در یک جمله یاد بگیریم."},{"de":"Zum Beispiel merken Sie sich das Verb verbessern leichter mit dem Satz: Ich möchte meine Aussprache verbessern.","fa":"مثلاً فعل verbessern (بهتر کردن) را با جملهٔ «می‌خواهم تلفظم را بهتر کنم» راحت‌تر به خاطر می‌سپارید."},{"de":"Manche Menschen lernen besser, wenn sie die Wörter laut vorlesen oder hören.","fa":"بعضی آدم‌ها وقتی واژه‌ها را بلند می‌خوانند یا می‌شنوند، بهتر یاد می‌گیرند."},{"de":"Andere müssen die Wörter aufschreiben oder unterstreichen, um sie zu behalten.","fa":"بعضی دیگر باید واژه‌ها را بنویسند یا زیرشان خط بکشند تا در ذهنشان بماند."},{"de":"Probieren Sie verschiedene Methoden aus, um Ihren eigenen Lerntyp zu finden.","fa":"روش‌های مختلف را امتحان کنید تا سبک یادگیری خودتان را پیدا کنید."},{"de":"Ein letzter Tipp: Versuchen Sie, jeden Tag 15 Minuten zu lernen, statt einmal pro Woche zwei Stunden.","fa":"یک توصیهٔ آخر: سعی کنید به جای هفته‌ای یک بار دو ساعت، هر روز ۱۵ دقیقه درس بخوانید."},{"de":"Kurze Lernphasen sind nämlich viel effektiver als lange.","fa":"چون دوره‌های کوتاه یادگیری خیلی مؤثرتر از دوره‌های طولانی هستند."},{"de":"Und haben Sie keine Angst, Fehler zu machen, denn auch Fehler gehören zum Lernen.","fa":"و از اشتباه کردن نترسید، چون اشتباه هم بخشی از یادگیری است."},{"de":"Vielen Dank für Ihre Aufmerksamkeit, jetzt beantworte ich gern Ihre Fragen.","fa":"از توجه شما خیلی ممنونم؛ حالا با کمال میل به سؤال‌هایتان جواب می‌دهم."}],"q":[{"q":"Wie viel Prozent der neuen Wörter vergisst man ohne Wiederholung nach einer Woche?","opts":["fast 100 Prozent","etwa 15 Prozent","etwa 70 Prozent"],"a":2,"fa":"طبق پژوهش، بدون تکرار بعد از یک هفته حدود ۷۰ درصد واژه‌ها فراموش می‌شود."},{"q":"Wann sollte man ein Wort zum ersten Mal wiederholen?","opts":["nach einem Tag","nach einer Woche","nach einem Monat"],"a":0,"fa":"سخنران می‌گوید اولین تکرار «بعد از یک روز» باشد."},{"q":"Warum soll man Nomen mit Artikel und Plural lernen?","opts":["um schneller zu lesen","weil es im Test so verlangt wird","damit man später keine Fehler macht"],"a":2,"fa":"او می‌گوید اسم‌ها را با حرف تعریف و جمع یاد بگیرید «تا بعداً اشتباه نکنید»."},{"q":"Warum benutzen viele Lernende Karteikarten?","opts":["um die Wörter überall dabeizuhaben","weil der Lehrer es verlangt","weil sie billiger als Bücher sind"],"a":0,"fa":"خیلی‌ها از کارت استفاده می‌کنند «تا واژه‌ها همه جا همراهشان باشد»."},{"q":"Was empfiehlt der Sprecher zur Lernzeit?","opts":["einmal pro Woche zwei Stunden lernen","jeden Tag 15 Minuten lernen","nur vor der Prüfung lernen"],"a":1,"fa":"توصیهٔ آخر او این است که هر روز ۱۵ دقیقه درس بخوانید، نه هفته‌ای یک بار دو ساعت."},{"q":"Was sagt der Sprecher über Fehler?","opts":["Man sollte sie unbedingt vermeiden.","Fehler gehören zum Lernen.","Man sollte nur mündlich üben."],"a":1,"fa":"سخنران می‌گوید: «اشتباه هم بخشی از یادگیری است.»"}]},{"id":"h2","type":"Radiobeitrag","title":"Ausbildung oder Studium?","title_fa":"آموزش حرفه‌ای یا تحصیل دانشگاهی؟","intro_fa":"یک گزارشگر رادیو با استفاده از آمار دربارهٔ نظام آموزش حرفه‌ای دوگانه در آلمان و فرصت‌های آن صحبت می‌کند.","s":[{"de":"Nach dem Schulabschluss stellen sich viele junge Menschen die Frage: Studium oder Ausbildung?","fa":"بعد از پایان مدرسه، بسیاری از جوانان از خودشان می‌پرسند: دانشگاه یا آموزش حرفه‌ای؟"},{"de":"In Deutschland beginnen jedes Jahr fast eine halbe Million junge Leute eine duale Ausbildung.","fa":"در آلمان هر سال تقریباً نیم میلیون جوان یک دورهٔ آموزش حرفه‌ای دوگانه را شروع می‌کنند."},{"de":"Dual bedeutet, dass die Lehrlinge in einem Betrieb arbeiten und gleichzeitig eine Berufsschule besuchen.","fa":"دوگانه یعنی کارآموزان در یک شرکت کار می‌کنند و هم‌زمان به مدرسهٔ حرفه‌ای می‌روند."},{"de":"Meistens sind sie drei oder vier Tage pro Woche im Betrieb und ein bis zwei Tage in der Schule.","fa":"معمولاً سه یا چهار روز در هفته در شرکت و یک تا دو روز در مدرسه هستند."},{"de":"Ein großer Vorteil ist, dass man schon während der Ausbildung Geld verdient.","fa":"یک مزیت بزرگ این است که آدم از همان دوران آموزش پول درمی‌آورد."},{"de":"Im ersten Lehrjahr bekommen Auszubildende im Durchschnitt etwa 1000 Euro im Monat.","fa":"کارآموزان در سال اول به طور میانگین حدود ۱۰۰۰ یورو در ماه می‌گیرند."},{"de":"Eine aktuelle Statistik zeigt aber auch ein Problem.","fa":"اما یک آمار جدید مشکلی را هم نشان می‌دهد."},{"de":"Im letzten Jahr blieben rund siebzigtausend Lehrstellen frei, weil die Betriebe keine passenden Bewerber gefunden haben.","fa":"سال گذشته حدود هفتاد هزار جای کارآموزی خالی ماند، چون شرکت‌ها متقاضی مناسبی پیدا نکردند."},{"de":"Besonders im Handwerk, zum Beispiel bei Bäckern oder Elektrikern, fehlen Lehrlinge.","fa":"به‌خصوص در مشاغل فنی و صنعتگری، مثلاً در نانوایی‌ها یا میان برق‌کارها، کارآموز کم است."},{"de":"Gleichzeitig entscheiden sich immer mehr Jugendliche für ein Studium an der Universität.","fa":"در همین حال، نوجوانان بیشتر و بیشتری تحصیل در دانشگاه را انتخاب می‌کنند."},{"de":"Viele Eltern glauben nämlich, dass ein Studium bessere Chancen bietet.","fa":"چون بسیاری از والدین فکر می‌کنند تحصیل دانشگاهی فرصت‌های بهتری فراهم می‌کند."},{"de":"Experten sehen das anders: Wer eine Lehre abgeschlossen hat, findet meistens schnell eine Stelle.","fa":"کارشناسان نظر دیگری دارند: کسی که دورهٔ کارآموزی را تمام کرده، معمولاً زود کار پیدا می‌کند."},{"de":"Außerdem kann man sich nach der Ausbildung zum Meister weiterbilden.","fa":"علاوه بر این، بعد از دورهٔ آموزش می‌توان با آموزش تکمیلی استادکار شد."},{"de":"Mit dem Meistertitel ist es sogar möglich, ohne Abitur zu studieren.","fa":"با عنوان استادکار حتی می‌شود بدون دیپلم دبیرستان در دانشگاه درس خواند."},{"de":"Um mehr Jugendliche zu gewinnen, bieten viele Betriebe jetzt Praktika in den Ferien an.","fa":"برای جذب نوجوانان بیشتر، بسیاری از شرکت‌ها حالا در تعطیلات دورهٔ کارورزی ارائه می‌دهند."},{"de":"So können Schüler einen Beruf testen, bevor sie sich entscheiden.","fa":"به این ترتیب دانش‌آموزان می‌توانند پیش از تصمیم‌گیری یک شغل را امتحان کنند."},{"de":"Wer Interesse hat, findet Informationen bei der Berufsberatung der Arbeitsagentur.","fa":"هر کس علاقه دارد، می‌تواند در بخش مشاورهٔ شغلی ادارهٔ کار اطلاعات بگیرد."}],"q":[{"q":"Was bedeutet duale Ausbildung?","opts":["Man arbeitet im Betrieb und besucht eine Berufsschule.","Man lernt zwei Berufe gleichzeitig.","Man studiert an zwei Universitäten."],"a":0,"fa":"«دوگانه» یعنی کار در شرکت و هم‌زمان رفتن به مدرسهٔ حرفه‌ای."},{"q":"Wie viel verdienen Auszubildende im ersten Lehrjahr im Durchschnitt?","opts":["etwa 500 Euro im Monat","etwa 1000 Euro im Monat","nichts"],"a":1,"fa":"گزارشگر می‌گوید در سال اول به طور میانگین حدود ۱۰۰۰ یورو در ماه."},{"q":"Warum blieben im letzten Jahr viele Lehrstellen frei?","opts":["weil die Ausbildung zu teuer ist","weil die Berufsschulen geschlossen waren","weil die Betriebe keine passenden Bewerber gefunden haben"],"a":2,"fa":"جاهای کارآموزی خالی ماند «چون شرکت‌ها متقاضی مناسبی پیدا نکردند»."},{"q":"Wo fehlen besonders viele Lehrlinge?","opts":["im Handwerk","an Universitäten","in Banken"],"a":0,"fa":"به‌خصوص در مشاغل فنی مثل نانوایی و برق‌کاری کارآموز کم است."},{"q":"Was sagen Experten über Leute mit abgeschlossener Lehre?","opts":["Sie verdienen weniger als Studenten.","Sie müssen danach studieren.","Sie finden meistens schnell eine Stelle."],"a":2,"fa":"کارشناسان می‌گویند کسی که کارآموزی را تمام کرده معمولاً زود کار پیدا می‌کند."},{"q":"Was bieten viele Betriebe an, um Jugendliche zu gewinnen?","opts":["Praktika in den Ferien","kostenlose Sprachkurse","höhere Gehälter für Schüler"],"a":0,"fa":"شرکت‌ها برای جذب نوجوانان در تعطیلات دورهٔ کارورزی ارائه می‌دهند."}]}],"5":[{"id":"h1","type":"Podcast-Folge","title":"Gesund durch den Winter","title_fa":"سالم در زمستان","intro_fa":"مجری یک پادکست سلامت به سؤال شنوندگان دربارهٔ پیشگیری از سرماخوردگی جواب می‌دهد و توصیه‌هایی می‌کند.","s":[{"de":"Hallo und willkommen zu einer neuen Folge von Gesund im Alltag!","fa":"سلام، به قسمت جدید «سلامت در زندگی روزمره» خوش آمدید!"},{"de":"Im Winter leiden viele Menschen unter Erkältungen, Schnupfen und Husten.","fa":"در زمستان بسیاری از مردم از سرماخوردگی، آبریزش بینی و سرفه رنج می‌برند."},{"de":"Viele von Ihnen haben uns gefragt, ob man sich gegen eine Erkältung schützen kann.","fa":"بسیاری از شما از ما پرسیده‌اید که آیا می‌شود از خود در برابر سرماخوردگی محافظت کرد."},{"de":"Die gute Nachricht ist: Ja, mit ein paar einfachen Regeln geht das.","fa":"خبر خوب این است: بله، با چند قانون ساده می‌شود."},{"de":"Zuerst sollten Sie sich oft und gründlich die Hände waschen, mindestens 20 Sekunden lang.","fa":"اول اینکه باید دست‌هایتان را زیاد و با دقت بشویید، دست‌کم ۲۰ ثانیه."},{"de":"Viren kommen nämlich meistens über die Hände in die Nase oder in den Mund.","fa":"چون ویروس‌ها بیشتر از راه دست وارد بینی یا دهان می‌شوند."},{"de":"Außerdem wäre es gut, jeden Tag mindestens eine halbe Stunde an die frische Luft zu gehen.","fa":"علاوه بر این، خوب است هر روز دست‌کم نیم ساعت در هوای آزاد باشید."},{"de":"Auch wenn es kalt ist, stärkt Bewegung das Immunsystem.","fa":"حتی وقتی هوا سرد است، تحرک سیستم ایمنی را تقویت می‌کند."},{"de":"Ich persönlich würde auch auf die Ernährung achten: Viel Obst, Gemüse und warmer Tee helfen dem Körper.","fa":"من خودم به تغذیه هم توجه می‌کردم: میوه و سبزی زیاد و چای گرم به بدن کمک می‌کنند."},{"de":"Und wenn Sie schon erkältet sind, sollten Sie zu Hause bleiben, statt ins Büro zu gehen.","fa":"و اگر سرما خورده‌اید، بهتر است به جای رفتن به اداره در خانه بمانید."},{"de":"Wenn alle Kranken zu Hause bleiben würden, gäbe es viel weniger Infektionen.","fa":"اگر همهٔ بیماران در خانه می‌ماندند، عفونت‌ها خیلی کمتر می‌شد."},{"de":"Oft fragen Hörer auch, wann man zum Arzt gehen sollte.","fa":"شنوندگان اغلب می‌پرسند چه وقت باید به پزشک مراجعه کرد."},{"de":"Wenn Sie hohes Fieber haben oder schlecht atmen können, sollten Sie nicht warten.","fa":"اگر تب بالا دارید یا به سختی نفس می‌کشید، نباید صبر کنید."},{"de":"Das Gleiche gilt, wenn die Erkältung länger als zehn Tage dauert.","fa":"همین موضوع وقتی هم صدق می‌کند که سرماخوردگی بیش از ده روز طول بکشد."},{"de":"Antibiotika helfen übrigens nicht gegen eine Erkältung, weil sie von Viren kommt.","fa":"راستی آنتی‌بیوتیک‌ها برای سرماخوردگی فایده ندارند، چون سرماخوردگی را ویروس‌ها ایجاد می‌کنند."},{"de":"Und denken Sie an genug Schlaf, denn müde Menschen werden schneller krank.","fa":"و خواب کافی را فراموش نکنید، چون آدم‌های خسته زودتر بیمار می‌شوند."},{"de":"In der nächsten Folge sprechen wir darüber, wie man gesund kocht, ohne viel Zeit zu brauchen.","fa":"در قسمت بعد دربارهٔ این صحبت می‌کنیم که چطور می‌شود بدون صرف وقت زیاد، سالم آشپزی کرد."}],"q":[{"q":"Wie lange sollte man sich die Hände waschen?","opts":["mindestens 20 Sekunden","etwa 5 Sekunden","mindestens 2 Minuten"],"a":0,"fa":"مجری می‌گوید دست‌ها را «دست‌کم ۲۰ ثانیه» بشویید."},{"q":"Wie kommen Viren meistens in die Nase oder in den Mund?","opts":["über das Wasser","über das Essen","über die Hände"],"a":2,"fa":"ویروس‌ها بیشتر از راه دست وارد بینی یا دهان می‌شوند."},{"q":"Was sollte man tun, wenn man schon erkältet ist?","opts":["mehr Sport machen","Antibiotika nehmen","zu Hause bleiben"],"a":2,"fa":"مجری می‌گوید اگر سرما خورده‌اید، به جای رفتن به اداره در خانه بمانید."},{"q":"Wann sollte man zum Arzt gehen?","opts":["bei hohem Fieber oder Problemen beim Atmen","schon beim ersten Schnupfen","nur im Sommer"],"a":0,"fa":"در صورت تب بالا یا مشکل تنفس نباید صبر کرد."},{"q":"Warum helfen Antibiotika nicht gegen eine Erkältung?","opts":["weil sie müde machen","weil die Erkältung von Viren kommt","weil sie zu teuer sind"],"a":1,"fa":"آنتی‌بیوتیک کمکی نمی‌کند، چون سرماخوردگی را ویروس ایجاد می‌کند."},{"q":"Worum geht es in der nächsten Folge?","opts":["um Sport im Winter","um Schlafprobleme","um schnelles, gesundes Kochen"],"a":2,"fa":"قسمت بعد دربارهٔ آشپزی سالم بدون صرف وقت زیاد است."}]},{"id":"h2","type":"Sprachnachricht","title":"Sprachnachricht aus dem Krankenhaus","title_fa":"پیام صوتی از بیمارستان","intro_fa":"مارکوس بعد از یک حادثهٔ ورزشی از بیمارستان برای دوستش آنا پیام می‌گذارد و از او کمک می‌خواهد.","s":[{"de":"Hallo Anna, hier ist Markus, ich liege gerade im Krankenhaus, aber keine Sorge, es ist nicht so schlimm.","fa":"سلام آنا، مارکوس هستم؛ الان در بیمارستان بستری‌ام، ولی نگران نباش، خیلی جدی نیست."},{"de":"Gestern bin ich beim Fußballspielen gestürzt und habe mich am Knie verletzt.","fa":"دیروز موقع فوتبال بازی کردن زمین خوردم و زانویم آسیب دید."},{"de":"Zuerst dachte ich, es wäre nur eine kleine Wunde, aber das Knie wurde schnell dick.","fa":"اول فکر کردم فقط یک زخم کوچک است، اما زانویم زود ورم کرد."},{"de":"Ein Freund hat mich dann in die Notaufnahme gebracht.","fa":"بعد یکی از دوستانم مرا به اورژانس رساند."},{"de":"Dort haben die Ärzte mein Knie geröntgt, und zum Glück ist der Knochen nicht gebrochen.","fa":"آنجا پزشکان از زانویم عکس رادیولوژی گرفتند و خوشبختانه استخوان نشکسته است."},{"de":"Aber ein Band ist gerissen, deshalb muss ich morgen operiert werden.","fa":"اما یک رباط پاره شده و به همین دلیل باید فردا عمل شوم."},{"de":"Ich weiß noch nicht, wie lange ich in der Klinik bleiben muss.","fa":"هنوز نمی‌دانم چه مدت باید در بیمارستان بمانم."},{"de":"Der Arzt hat gesagt, dass ich danach mindestens sechs Wochen nicht Fußball spielen darf.","fa":"دکتر گفته که بعد از آن دست‌کم شش هفته نباید فوتبال بازی کنم."},{"de":"Ich habe ihn auch gefragt, ob ich bald wieder arbeiten kann.","fa":"از او پرسیدم که آیا به زودی می‌توانم دوباره سر کار بروم."},{"de":"Ins Büro kann ich wahrscheinlich nach zwei Wochen wieder gehen, wenn ich Krücken benutze.","fa":"احتمالاً بعد از دو هفته، اگر از عصای زیر بغل استفاده کنم، می‌توانم دوباره به اداره بروم."},{"de":"Ich hätte eine große Bitte an dich.","fa":"یک خواهش بزرگ از تو داشتم."},{"de":"Könntest du heute Abend in meine Wohnung gehen und mir ein paar Sachen holen?","fa":"ممکن است امشب به آپارتمانم بروی و چند تا وسیله برایم بیاوری؟"},{"de":"Ich bräuchte vor allem mein Ladekabel, ein Buch und frische Kleidung.","fa":"مخصوصاً به شارژر گوشی‌ام، یک کتاب و لباس تمیز نیاز دارم."},{"de":"Den Schlüssel hat meine Nachbarin, Frau Yilmaz, im zweiten Stock.","fa":"کلید پیش همسایه‌ام، خانم ییلماز، در طبقهٔ دوم است."},{"de":"Und weißt du vielleicht, ob die Krankenkasse auch die Physiotherapie bezahlt?","fa":"راستی تو می‌دانی بیمهٔ درمانی هزینهٔ فیزیوتراپی را هم می‌پردازد یا نه؟"},{"de":"Die Besuchszeit ist bis 20 Uhr, ich liege in Zimmer 214.","fa":"ساعت ملاقات تا ساعت ۲۰ است؛ من در اتاق ۲۱۴ هستم."},{"de":"Danke dir schon mal und bis heute Abend!","fa":"از الان ممنونم، تا امشب!"}],"q":[{"q":"Wie hat sich Markus verletzt?","opts":["beim Fahrradfahren","bei der Arbeit","beim Fußballspielen"],"a":2,"fa":"مارکوس می‌گوید «موقع فوتبال بازی کردن» زمین خورده است."},{"q":"Was haben die Ärzte festgestellt?","opts":["Der Knochen ist gebrochen.","Es ist nur eine kleine Wunde.","Der Knochen ist nicht gebrochen, aber ein Band ist gerissen."],"a":2,"fa":"پزشکان گفتند استخوان نشکسته، اما یک رباط پاره شده است."},{"q":"Wie lange darf Markus nicht Fußball spielen?","opts":["mindestens sechs Wochen","ein Jahr","zwei Wochen"],"a":0,"fa":"دکتر گفته دست‌کم شش هفته نباید فوتبال بازی کند؛ دو هفته مربوط به برگشتن به اداره است."},{"q":"Worum bittet Markus Anna?","opts":["Sie soll ihn morgen abholen.","Sie soll ihm Sachen aus seiner Wohnung holen.","Sie soll seinen Chef anrufen."],"a":1,"fa":"مارکوس از آنا می‌خواهد به آپارتمانش برود و چند وسیله برایش بیاورد."},{"q":"Wer hat den Schlüssel zu seiner Wohnung?","opts":["seine Nachbarin Frau Yilmaz","Anna","sein Freund vom Fußball"],"a":0,"fa":"کلید پیش همسایه‌اش، خانم ییلماز، است."},{"q":"Bis wann ist die Besuchszeit?","opts":["bis 22 Uhr","bis 20 Uhr","bis 18 Uhr"],"a":1,"fa":"او می‌گوید ساعت ملاقات تا ساعت ۲۰ است."}]}],"6":[{"id":"h1","type":"Radiobeitrag","title":"Wie verbringen die Deutschen ihre Freizeit?","title_fa":"آلمانی‌ها اوقات فراغتشان را چگونه می‌گذرانند؟","intro_fa":"گوینده‌ی یک برنامه‌ی رادیویی نتایج یک نظرسنجی جدید درباره‌ی اوقات فراغت مردم آلمان را گزارش می‌دهد.","s":[{"de":"Herzlich willkommen zu unserer Sendung „Freizeit heute“.","fa":"به برنامه‌ی «اوقات فراغت امروز» خیلی خوش آمدید."},{"de":"Heute geht es um die Frage, wie die Menschen in Deutschland ihre freie Zeit verbringen.","fa":"امروز موضوع این پرسش است که مردم در آلمان وقت آزادشان را چگونه می‌گذرانند."},{"de":"Eine neue Umfrage mit über 2000 Teilnehmern zeigt interessante Ergebnisse.","fa":"یک نظرسنجی جدید با بیش از ۲۰۰۰ شرکت‌کننده نتایج جالبی نشان می‌دهد."},{"de":"Die beliebteste Aktivität ist immer noch das Fernsehen, aber das Internet wird jedes Jahr wichtiger.","fa":"محبوب‌ترین فعالیت هنوز هم تماشای تلویزیون است، اما اینترنت هر سال مهم‌تر می‌شود."},{"de":"Besonders junge Leute verbringen mehr Zeit am Handy als vor dem Fernseher.","fa":"به‌خصوص جوان‌ها وقت بیشتری را با موبایل می‌گذرانند تا جلوی تلویزیون."},{"de":"Auf dem zweiten Platz steht Musikhören, auf dem dritten Platz der Spaziergang in der Natur.","fa":"در رتبه‌ی دوم گوش دادن به موسیقی و در رتبه‌ی سوم پیاده‌روی در طبیعت قرار دارد."},{"de":"Viele Befragte sagen, dass ein langer Spaziergang für sie entspannender ist als jeder Film.","fa":"بسیاری از پاسخ‌دهندگان می‌گویند که یک پیاده‌روی طولانی برایشان آرامش‌بخش‌تر از هر فیلمی است."},{"de":"Ältere Menschen treffen sich gern mit Freunden oder arbeiten im eigenen Garten.","fa":"افراد مسن‌تر دوست دارند با دوستانشان دیدار کنند یا در باغچه‌ی خودشان کار کنند."},{"de":"Fast jeder dritte Deutsche ist Mitglied in einem Verein, zum Beispiel in einem Sportverein oder in einem Chor.","fa":"تقریباً از هر سه آلمانی یک نفر عضو یک انجمن است، مثلاً یک باشگاه ورزشی یا یک گروه کُر."},{"de":"Interessant ist auch: Je mehr Menschen arbeiten, desto wichtiger wird für sie die Erholung am Wochenende.","fa":"این هم جالب است: هرچه آدم‌ها بیشتر کار کنند، استراحت در آخر هفته برایشان مهم‌تر می‌شود."},{"de":"Viele möchten am Samstag einfach nur faulenzen und lange schlafen.","fa":"خیلی‌ها می‌خواهند روز شنبه فقط تنبلی کنند و تا دیروقت بخوابند."},{"de":"Andere suchen das Abenteuer und gehen klettern oder machen eine Wanderung in den Bergen.","fa":"عده‌ای دیگر دنبال ماجراجویی هستند و به صخره‌نوردی می‌روند یا در کوهستان کوه‌پیمایی می‌کنند."},{"de":"Die Forscher haben auch gefragt, wofür die Leute gern mehr Zeit hätten.","fa":"پژوهشگران همچنین پرسیده‌اند که مردم دوست داشتند برای چه چیزی وقت بیشتری داشته باشند."},{"de":"Die häufigste Antwort war: für die Familie und für gute Freunde.","fa":"رایج‌ترین پاسخ این بود: برای خانواده و دوستان خوب."},{"de":"Erst danach kamen Reisen und neue Hobbys.","fa":"فقط بعد از آن سفر و سرگرمی‌های جدید قرار گرفتند."},{"de":"Unser Tipp für dieses Wochenende: Probieren Sie doch einmal etwas Neues aus!","fa":"پیشنهاد ما برای این آخر هفته: یک بار چیز تازه‌ای را امتحان کنید!"},{"de":"Im Tierpark gibt es zum Beispiel am Sonntag ein großes Familienfest mit freiem Eintritt.","fa":"مثلاً روز یکشنبه در باغ‌وحش یک جشن بزرگ خانوادگی با ورود رایگان برگزار می‌شود."}],"q":[{"q":"Was ist laut Umfrage die beliebteste Freizeitaktivität?","opts":["Musikhören","ein Spaziergang in der Natur","Fernsehen"],"a":2,"fa":"گوینده می‌گوید: «محبوب‌ترین فعالیت هنوز هم تماشای تلویزیون است»."},{"q":"Was sagt der Beitrag über junge Leute?","opts":["Sie sehen mehr fern als ältere Menschen.","Sie arbeiten gern im Garten.","Sie verbringen mehr Zeit am Handy als vor dem Fernseher."],"a":2,"fa":"در متن آمده که جوان‌ها وقت بیشتری با موبایل می‌گذرانند تا جلوی تلویزیون."},{"q":"Wie viele Deutsche sind Mitglied in einem Verein?","opts":["fast jeder dritte","fast jeder zehnte","fast jeder zweite"],"a":0,"fa":"گوینده می‌گوید: «تقریباً از هر سه آلمانی یک نفر عضو یک انجمن است»."},{"q":"Was machen viele Menschen gern am Samstag?","opts":["lange arbeiten","faulenzen und lange schlafen","in den Chor gehen"],"a":1,"fa":"خیلی‌ها می‌خواهند شنبه فقط تنبلی کنند و تا دیروقت بخوابند."},{"q":"Wofür hätten die Menschen am liebsten mehr Zeit?","opts":["für Reisen","für Familie und Freunde","für neue Hobbys"],"a":1,"fa":"رایج‌ترین پاسخ «برای خانواده و دوستان خوب» بود؛ سفر و سرگرمی بعد از آن آمدند."},{"q":"Was gibt es am Sonntag im Tierpark?","opts":["einen Kletterkurs für Kinder","ein Familienfest mit freiem Eintritt","ein Konzert mit teuren Karten"],"a":1,"fa":"در پایان گفته می‌شود که یکشنبه در باغ‌وحش یک جشن خانوادگی با ورود رایگان برگزار می‌شود."}]},{"id":"h2","type":"Führung","title":"Ein Rundgang durch das Stadtmuseum","title_fa":"گشتی در موزه‌ی شهر","intro_fa":"یک راهنمای موزه گروهی از بازدیدکنندگان را در موزه‌ی شهر همراهی می‌کند و بخش‌های مختلف را معرفی می‌کند.","s":[{"de":"Guten Tag, meine Damen und Herren, und herzlich willkommen im Stadtmuseum!","fa":"روز بخیر، خانم‌ها و آقایان، به موزه‌ی شهر خیلی خوش آمدید!"},{"de":"Mein Name ist Thomas Berger, und ich begleite Sie heute eine Stunde lang durch unsere Ausstellung.","fa":"اسم من توماس برگر است و امروز یک ساعت شما را در نمایشگاهمان همراهی می‌کنم."},{"de":"Bitte bleiben Sie in der Gruppe und fotografieren Sie nur ohne Blitz.","fa":"لطفاً در گروه بمانید و فقط بدون فلاش عکس بگیرید."},{"de":"Wir beginnen hier im ersten Raum mit altem Spielzeug aus dem neunzehnten Jahrhundert.","fa":"ما اینجا در اتاق اول با اسباب‌بازی‌های قدیمی از قرن نوزدهم شروع می‌کنیم."},{"de":"Die kleine Puppe mit dem roten Kleid ist unser ältestes Stück, denn sie ist fast 200 Jahre alt.","fa":"عروسک کوچک با لباس قرمز قدیمی‌ترین شیء ماست، چون تقریباً ۲۰۰ سال قدمت دارد."},{"de":"Damals hatten Kinder viel weniger Spielzeug als heute, und es war meistens aus Holz.","fa":"آن زمان بچه‌ها خیلی کمتر از امروز اسباب‌بازی داشتند و اسباب‌بازی‌ها معمولاً چوبی بودند."},{"de":"Jetzt gehen wir in den großen Saal mit den modernen Bildern.","fa":"حالا به سالن بزرگ با تابلوهای مدرن می‌رویم."},{"de":"Hier sehen Sie Werke von jungen Künstlern aus unserer Region.","fa":"اینجا آثار هنرمندان جوانی از منطقه‌ی ما را می‌بینید."},{"de":"Das größte Bild an der rechten Wand hat eine junge Malerin mit nur 22 Jahren gemalt.","fa":"بزرگ‌ترین تابلو روی دیوار سمت راست را یک نقاش جوان در فقط ۲۲ سالگی کشیده است."},{"de":"Viele Besucher finden es schöner als die berühmten Bilder in den großen Museen.","fa":"بسیاری از بازدیدکنندگان آن را زیباتر از تابلوهای معروف موزه‌های بزرگ می‌دانند."},{"de":"Im nächsten Raum geht es um Literatur.","fa":"اتاق بعدی درباره‌ی ادبیات است."},{"de":"Hier können Sie alte Bücher, Briefe und Fotos von bekannten Schriftstellern aus unserer Stadt entdecken.","fa":"اینجا می‌توانید کتاب‌ها، نامه‌ها و عکس‌های قدیمی نویسندگان مشهور شهرمان را کشف کنید."},{"de":"Für Kinder gibt es in diesem Raum ein kleines Spiel, bei dem sie fünf versteckte Tiere in den Bildern finden müssen.","fa":"برای بچه‌ها در این اتاق یک بازی کوچک هست که در آن باید پنج حیوان پنهان‌شده را در تصویرها پیدا کنند."},{"de":"Am Ende des Rundgangs kommen wir in unser gemütliches Museumscafé.","fa":"در پایان گشت به کافه‌ی دنج موزه می‌رسیم."},{"de":"Dort können Sie bei einem heißen Kaffee und einem frischen Kuchen eine Pause genießen.","fa":"آنجا می‌توانید با یک قهوه‌ی داغ و یک کیک تازه از استراحت لذت ببرید."},{"de":"Mit Ihrer Eintrittskarte bekommen Sie dort übrigens zehn Prozent Rabatt.","fa":"راستی با بلیت ورودتان آنجا ده درصد تخفیف می‌گیرید."},{"de":"Jeden ersten Freitag im Monat ist das Museum bis 22 Uhr geöffnet, und es gibt Live-Musik.","fa":"اولین جمعه‌ی هر ماه موزه تا ساعت ۲۲ باز است و موسیقی زنده اجرا می‌شود."}],"q":[{"q":"Wie lange dauert die Führung?","opts":["eine Stunde","eine halbe Stunde","zwei Stunden"],"a":0,"fa":"راهنما می‌گوید: «امروز یک ساعت شما را همراهی می‌کنم»."},{"q":"Was ist das älteste Stück des Museums?","opts":["ein Bild einer jungen Malerin","eine Puppe mit einem roten Kleid","ein alter Brief"],"a":1,"fa":"عروسک کوچک با لباس قرمز قدیمی‌ترین شیء است و تقریباً ۲۰۰ سال دارد."},{"q":"Woraus war das Spielzeug früher meistens?","opts":["aus Holz","aus Plastik","aus Metall"],"a":0,"fa":"در متن آمده که اسباب‌بازی‌ها آن زمان معمولاً چوبی بودند."},{"q":"Was sollen Kinder im Literaturraum machen?","opts":["fünf versteckte Tiere finden","ein Buch vorlesen","ein Bild malen"],"a":0,"fa":"بچه‌ها باید پنج حیوان پنهان‌شده را در تصویرها پیدا کنند."},{"q":"Was bekommt man mit der Eintrittskarte im Café?","opts":["einen Kaffee gratis","ein Stück Kuchen gratis","zehn Prozent Rabatt"],"a":2,"fa":"راهنما می‌گوید با بلیت ورود در کافه ده درصد تخفیف می‌گیرید."},{"q":"Was gibt es jeden ersten Freitag im Monat?","opts":["längere Öffnungszeiten und Live-Musik","eine Führung nur für Kinder","freien Eintritt"],"a":0,"fa":"اولین جمعه‌ی هر ماه موزه تا ساعت ۲۲ باز است و موسیقی زنده دارد؛ از ورود رایگان حرفی زده نشد."}]}],"7":[{"id":"h1","type":"Nachrichten","title":"Verkehrsmeldungen am Freitagnachmittag","title_fa":"اخبار ترافیک در بعدازظهر جمعه","intro_fa":"گوینده‌ی یک رادیوی محلی بعدازظهر جمعه وضعیت جاده‌ها و حمل‌ونقل عمومی را اعلام می‌کند.","s":[{"de":"Hier ist Radio Süd mit den aktuellen Verkehrsmeldungen für Freitagnachmittag.","fa":"اینجا رادیو زود است با تازه‌ترین اخبار ترافیک برای بعدازظهر جمعه."},{"de":"Wie jeden Freitag sind die Straßen um diese Zeit sehr voll, weil viele Menschen ins Wochenende fahren.","fa":"مثل هر جمعه، جاده‌ها در این ساعت خیلی شلوغ است، چون خیلی‌ها برای آخر هفته به سفر می‌روند."},{"de":"Auf der Autobahn zwischen München und Salzburg gibt es zurzeit 12 Kilometer Stau.","fa":"در بزرگراه بین مونیخ و سالزبورگ در حال حاضر ۱۲ کیلومتر ترافیک سنگین است."},{"de":"Dort ist ein Lastwagen mit einer Panne liegen geblieben, und eine Spur ist gesperrt.","fa":"آنجا یک کامیون خراب شده و مانده است و یک لاین بسته شده است."},{"de":"Der Lastwagen wird gerade von der Polizei abgeschleppt.","fa":"کامیون در حال حاضر توسط پلیس یدک‌کشی می‌شود."},{"de":"Rechnen Sie dort mit einer Verspätung von etwa 40 Minuten.","fa":"آنجا حدود ۴۰ دقیقه تأخیر را در نظر بگیرید."},{"de":"In der Innenstadt wird seit Montag die Hauptstraße repariert.","fa":"در مرکز شهر از دوشنبه خیابان اصلی در حال تعمیر است."},{"de":"Deshalb ist sie bis Ende des Monats eine Einbahnstraße, und es wurde eine Umleitung eingerichtet.","fa":"به همین دلیل این خیابان تا آخر ماه یک‌طرفه است و یک مسیر انحرافی ایجاد شده است."},{"de":"Autofahrer, die zum Bahnhof wollen, sollten an der Kreuzung beim Rathaus links abbiegen.","fa":"رانندگانی که می‌خواهند به ایستگاه قطار بروند، باید سر چهارراه کنار شهرداری به چپ بپیچند."},{"de":"Bitte achten Sie dort auf die neuen Verkehrszeichen.","fa":"لطفاً آنجا به علائم راهنمایی جدید توجه کنید."},{"de":"Auch im öffentlichen Verkehr gibt es heute Probleme.","fa":"امروز در حمل‌ونقل عمومی هم مشکلاتی وجود دارد."},{"de":"Die S-Bahn-Linie 3 fällt wegen eines technischen Problems zwischen Hauptbahnhof und Flughafen aus.","fa":"خط ۳ قطار شهری به دلیل یک مشکل فنی بین ایستگاه مرکزی و فرودگاه حرکت نمی‌کند."},{"de":"Als Ersatz werden Busse eingesetzt, die alle 15 Minuten fahren.","fa":"به جای آن اتوبوس‌هایی به کار گرفته شده‌اند که هر ۱۵ دقیقه حرکت می‌کنند."},{"de":"Die Straßenbahn fährt dagegen ohne Verspätungen.","fa":"در عوض تراموا بدون تأخیر حرکت می‌کند."},{"de":"Und jetzt noch eine Warnung: Am Abend wird starker Regen erwartet.","fa":"و حالا یک هشدار: برای عصر باران شدید پیش‌بینی می‌شود."},{"de":"Die Fahrbahnen können dann sehr glatt werden, also fahren Sie bitte langsam und halten Sie genug Abstand.","fa":"آن وقت سطح جاده‌ها ممکن است خیلی لغزنده شود، پس لطفاً آهسته برانید و فاصله‌ی کافی را رعایت کنید."},{"de":"In einer Stunde hören Sie die nächsten Verkehrsmeldungen.","fa":"یک ساعت دیگر اخبار بعدی ترافیک را می‌شنوید."},{"de":"Wir wünschen Ihnen eine gute und sichere Fahrt!","fa":"برایتان سفری خوب و ایمن آرزو می‌کنیم!"}],"q":[{"q":"Warum gibt es Stau zwischen München und Salzburg?","opts":["wegen eines Lastwagens mit einer Panne","wegen einer großen Baustelle","wegen eines Unfalls mit zwei Autos"],"a":0,"fa":"گوینده می‌گوید یک کامیون خراب شده و مانده و یک لاین بسته است."},{"q":"Mit wie viel Verspätung muss man dort ungefähr rechnen?","opts":["mit etwa 40 Minuten","mit etwa zwei Stunden","mit etwa 12 Minuten"],"a":0,"fa":"در متن آمده: «حدود ۴۰ دقیقه تأخیر را در نظر بگیرید». عدد ۱۲ مربوط به کیلومترهای ترافیک است."},{"q":"Was passiert seit Montag in der Innenstadt?","opts":["Die Hauptstraße wird repariert.","Eine neue Fußgängerzone wird gebaut.","Die Hauptstraße ist ganz geschlossen."],"a":0,"fa":"خیابان اصلی از دوشنبه تعمیر می‌شود و تا آخر ماه یک‌طرفه است، نه کاملاً بسته."},{"q":"Wie kommen Autofahrer zum Bahnhof?","opts":["Sie biegen an der Kreuzung rechts ab.","Sie biegen an der Kreuzung beim Rathaus links ab.","Sie fahren an der Kreuzung geradeaus."],"a":1,"fa":"گوینده می‌گوید رانندگان باید سر چهارراه کنار شهرداری به چپ بپیچند."},{"q":"Was fährt heute zwischen Hauptbahnhof und Flughafen?","opts":["nur Taxis","die S-Bahn-Linie 3","Ersatzbusse"],"a":2,"fa":"خط ۳ قطار شهری حرکت نمی‌کند و به جای آن اتوبوس‌های جایگزین هر ۱۵ دقیقه می‌روند."},{"q":"Wovor warnt der Sprecher am Ende?","opts":["vor Schnee in den Bergen","vor dichtem Nebel","vor starkem Regen und glatten Straßen"],"a":2,"fa":"هشدار درباره‌ی باران شدید عصر و جاده‌های لغزنده است."}]},{"id":"h2","type":"Podcast-Folge","title":"Ohne Auto durch Europa","title_fa":"سفر در اروپا بدون ماشین","intro_fa":"یونس، گوینده‌ی یک پادکست سفر، از برنامه‌اش برای یک سفر تابستانی بدون ماشین و هواپیما تعریف می‌کند.","s":[{"de":"Hallo und willkommen zu einer neuen Folge von „Unterwegs“, dem Reise-Podcast!","fa":"سلام، به قسمت تازه‌ای از «در راه»، پادکست سفر، خوش آمدید!"},{"de":"Ich bin Jonas, und heute erzähle ich euch von meinen Plänen für den Sommer.","fa":"من یونس هستم و امروز درباره‌ی برنامه‌هایم برای تابستان برایتان تعریف می‌کنم."},{"de":"Ich werde drei Wochen lang durch Europa reisen, und zwar komplett ohne Auto und ohne Flugzeug.","fa":"سه هفته در اروپا سفر خواهم کرد، آن هم کاملاً بدون ماشین و بدون هواپیما."},{"de":"Letztes Jahr bin ich noch mit dem Auto nach Italien gefahren, aber ich habe fast mehr Zeit im Stau verbracht als am Strand.","fa":"پارسال هنوز با ماشین به ایتالیا رفتم، اما تقریباً بیشتر از ساحل، در ترافیک وقت گذراندم."},{"de":"Außerdem ist das Benzin inzwischen sehr teuer geworden.","fa":"علاوه بر این، بنزین در این مدت خیلی گران شده است."},{"de":"Deshalb werde ich dieses Mal nur mit dem Zug, mit dem Bus und mit dem Fahrrad unterwegs sein.","fa":"به همین دلیل این بار فقط با قطار، اتوبوس و دوچرخه در سفر خواهم بود."},{"de":"Meine Strecke beginnt in Hamburg und führt über Kopenhagen nach Stockholm.","fa":"مسیر من از هامبورگ شروع می‌شود و از راه کپنهاگ به استکهلم می‌رسد."},{"de":"Die Fahrkarten habe ich schon vor zwei Monaten gebucht, weil sie da viel günstiger waren.","fa":"بلیت‌ها را دو ماه پیش رزرو کردم، چون آن موقع خیلی ارزان‌تر بودند."},{"de":"Für die Nächte habe ich Zimmer in Jugendherbergen und bei privaten Gastgebern reserviert.","fa":"برای شب‌ها اتاق‌هایی در خوابگاه‌های جوانان و پیش میزبان‌های خصوصی رزرو کرده‌ام."},{"de":"Ein Hotel wäre natürlich bequemer, aber auch dreimal so teuer.","fa":"البته هتل راحت‌تر بود، اما سه برابر هم گران‌تر."},{"de":"Ich weiß, dass Züge manchmal ausfallen oder zu spät kommen.","fa":"می‌دانم که قطارها گاهی لغو می‌شوند یا دیر می‌رسند."},{"de":"Deshalb plane ich zwischen zwei Verbindungen immer mindestens eine Stunde Pause ein.","fa":"به همین خاطر بین دو قطار همیشه دست‌کم یک ساعت فاصله در نظر می‌گیرم."},{"de":"Wenn ich einen Zug verpasse, bleibe ich eben einen Tag länger in einer schönen Stadt.","fa":"اگر قطاری را از دست بدهم، خب یک روز بیشتر در یک شهر زیبا می‌مانم."},{"de":"In Stockholm wird mich meine Schwester besuchen, und wir werden zusammen mit dem Rad durch die Stadt fahren.","fa":"در استکهلم خواهرم به دیدنم می‌آید و با هم با دوچرخه در شهر می‌گردیم."},{"de":"Die Reise wird wohl anstrengend werden, aber auch spannender als ein normaler Urlaub.","fa":"این سفر احتمالاً خسته‌کننده خواهد بود، اما هیجان‌انگیزتر از یک تعطیلات معمولی هم هست."},{"de":"In zwei Wochen erzähle ich euch in der nächsten Folge, wie meine erste Woche gelaufen ist.","fa":"دو هفته دیگر در قسمت بعدی برایتان تعریف می‌کنم که هفته‌ی اولم چطور گذشت."},{"de":"Bis dahin: Gute Reise und bleibt neugierig!","fa":"تا آن موقع: سفر خوبی داشته باشید و کنجکاو بمانید!"}],"q":[{"q":"Wie lange wird Jonas reisen?","opts":["zwei Monate","zwei Wochen","drei Wochen"],"a":2,"fa":"یونس می‌گوید: «سه هفته در اروپا سفر خواهم کرد». دو ماه پیش بلیت‌ها را خریده است."},{"q":"Warum fährt Jonas dieses Mal nicht mit dem Auto?","opts":["Sein Auto ist kaputt.","Er stand oft im Stau und das Benzin ist teuer.","Er hat keinen Führerschein."],"a":1,"fa":"او پارسال بیشتر وقتش را در ترافیک گذرانده و بنزین هم گران شده است."},{"q":"Wo beginnt die Reise?","opts":["in Kopenhagen","in Hamburg","in Stockholm"],"a":1,"fa":"مسیر از هامبورگ شروع می‌شود و از کپنهاگ به استکهلم می‌رود."},{"q":"Warum hat Jonas die Fahrkarten so früh gebucht?","opts":["Weil seine Schwester es wollte.","Weil die Züge sonst voll sind.","Weil sie da viel günstiger waren."],"a":2,"fa":"او می‌گوید بلیت‌ها را زود رزرو کرده چون آن موقع خیلی ارزان‌تر بودند."},{"q":"Was macht Jonas, weil Züge manchmal zu spät kommen?","opts":["Er plant immer mindestens eine Stunde Pause ein.","Er fährt lieber mit dem Bus.","Er nimmt dann ein Taxi."],"a":0,"fa":"او بین دو قطار همیشه دست‌کم یک ساعت فاصله در نظر می‌گیرد."},{"q":"Wer wird Jonas in Stockholm besuchen?","opts":["ein Freund aus Italien","seine Eltern","seine Schwester"],"a":2,"fa":"در متن آمده: «در استکهلم خواهرم به دیدنم می‌آید»."}]}],"8":[{"id":"h1","type":"Durchsage","title":"Aktionen im Einkaufszentrum","title_fa":"تخفیف‌ها و برنامه‌های ویژه در مرکز خرید","intro_fa":"از بلندگوی یک مرکز خرید، پیشنهادهای ویژه و اطلاعات مهم روز برای مشتریان اعلام می‌شود.","s":[{"de":"Liebe Kundinnen und Kunden, herzlich willkommen im Einkaufszentrum am Stadtpark!","fa":"مشتریان عزیز، به مرکز خرید کنار پارک شهر خیلی خوش آمدید!"},{"de":"Wegen der Eröffnung unseres neuen Elektronikgeschäfts im ersten Stock gibt es heute viele besondere Aktionen.","fa":"به مناسبت افتتاح فروشگاه جدید لوازم الکترونیکی ما در طبقه‌ی اول، امروز برنامه‌های ویژه‌ی زیادی داریم."},{"de":"Während der ganzen Woche bekommen Sie dort auf alle Fernseher und Laptops zwanzig Prozent Rabatt.","fa":"در طول تمام هفته آنجا روی همه‌ی تلویزیون‌ها و لپ‌تاپ‌ها بیست درصد تخفیف می‌گیرید."},{"de":"Die ersten hundert Käufer erhalten außerdem eine Tasche gratis.","fa":"صد خریدار اول علاوه بر این یک کیف رایگان دریافت می‌کنند."},{"de":"In unserer Drogerie im Erdgeschoss gibt es heute ein tolles Sonderangebot.","fa":"در داروخانه‌ی بهداشتی ما در طبقه‌ی همکف امروز یک پیشنهاد ویژه‌ی عالی هست."},{"de":"Jede zweite Packung Waschmittel bekommen Sie dort umsonst.","fa":"آنجا هر بسته‌ی دوم پودر لباس‌شویی را مجانی می‌گیرید."},{"de":"Die Buchhandlung neben dem Haupteingang lädt um 16 Uhr zu einer Lesung für Kinder ein.","fa":"کتاب‌فروشی کنار ورودی اصلی ساعت ۱۶ به یک کتاب‌خوانی برای کودکان دعوت می‌کند."},{"de":"Trotz des schlechten Wetters findet unser Bauernmarkt auf dem Parkplatz statt, und zwar unter einem großen Zelt.","fa":"با وجود هوای بد، بازار کشاورزان ما در پارکینگ برگزار می‌شود، آن هم زیر یک چادر بزرگ."},{"de":"Dort bieten Händler aus der Region frisches Obst, Gemüse und Käse an.","fa":"آنجا فروشندگانی از منطقه میوه، سبزی و پنیر تازه عرضه می‌کنند."},{"de":"Bitte beachten Sie: Wegen einer großen Lieferung ist der Eingang Nord heute bis 11 Uhr geschlossen.","fa":"لطفاً توجه کنید: به دلیل یک تحویل بار بزرگ، ورودی شمالی امروز تا ساعت ۱۱ بسته است."},{"de":"Benutzen Sie bitte stattdessen den Eingang am Parkhaus.","fa":"لطفاً به جای آن از ورودی کنار پارکینگ طبقاتی استفاده کنید."},{"de":"Wenn Sie Ihre Einkäufe nicht selbst tragen möchten, hilft Ihnen unser Lieferservice.","fa":"اگر نمی‌خواهید خریدهایتان را خودتان حمل کنید، سرویس تحویل ما به شما کمک می‌کند."},{"de":"Innerhalb der Stadt liefern wir ab einem Einkauf von 50 Euro kostenlos nach Hause.","fa":"داخل شهر برای خریدهای از ۵۰ یورو به بالا رایگان به خانه تحویل می‌دهیم."},{"de":"Außerhalb der Stadt kostet die Lieferung fünf Euro.","fa":"خارج از شهر هزینه‌ی تحویل پنج یورو است."},{"de":"Geschenke verpacken wir an unserer Information in der Mitte des Hauses gern für Sie.","fa":"هدیه‌ها را در باجه‌ی اطلاعات در وسط ساختمان با کمال میل برایتان بسته‌بندی می‌کنیم."},{"de":"Und denken Sie daran: Ohne Quittung ist ein Umtausch leider nicht möglich.","fa":"و یادتان باشد: متأسفانه تعویض کالا بدون رسید ممکن نیست."},{"de":"Wir wünschen Ihnen einen angenehmen Einkauf!","fa":"برایتان خریدی دلپذیر آرزو می‌کنیم!"}],"q":[{"q":"Warum gibt es heute viele Aktionen?","opts":["wegen der Eröffnung eines Elektronikgeschäfts","wegen des schlechten Wetters","wegen eines Jubiläums"],"a":0,"fa":"برنامه‌های ویژه به مناسبت افتتاح فروشگاه جدید لوازم الکترونیکی در طبقه‌ی اول است."},{"q":"Was bekommen die ersten hundert Käufer im Elektronikgeschäft?","opts":["fünfzig Prozent Rabatt","einen Laptop gratis","eine Tasche gratis"],"a":2,"fa":"در متن آمده که صد خریدار اول یک کیف رایگان می‌گیرند."},{"q":"Wo findet der Bauernmarkt statt?","opts":["neben dem Haupteingang","im Erdgeschoss","unter einem Zelt auf dem Parkplatz"],"a":2,"fa":"بازار کشاورزان با وجود هوای بد زیر یک چادر بزرگ در پارکینگ برگزار می‌شود."},{"q":"Welcher Eingang ist bis 11 Uhr geschlossen?","opts":["der Haupteingang","der Eingang Nord","der Eingang am Parkhaus"],"a":1,"fa":"ورودی شمالی به دلیل تحویل بار تا ساعت ۱۱ بسته است و باید از ورودی پارکینگ استفاده کرد."},{"q":"Wann ist die Lieferung innerhalb der Stadt kostenlos?","opts":["nur für Geschenke","immer","ab einem Einkauf von 50 Euro"],"a":2,"fa":"داخل شهر برای خرید از ۵۰ یورو به بالا تحویل رایگان است."},{"q":"Was braucht man für einen Umtausch?","opts":["eine Kundenkarte","eine Quittung","die Originalverpackung"],"a":1,"fa":"در پایان گفته می‌شود که بدون رسید تعویض ممکن نیست."}]},{"id":"h2","type":"Erklärvideo-Text","title":"So meldest du dich beim Bürgeramt an","title_fa":"ثبت آدرس در اداره‌ی امور شهروندی چگونه انجام می‌شود","intro_fa":"در یک ویدئوی آموزشی، گوینده توضیح می‌دهد که بعد از اسباب‌کشی چطور باید آدرس جدید را در اداره‌ی امور شهروندی ثبت کرد.","s":[{"de":"Du bist gerade in eine neue Wohnung gezogen und hast sicher viel zu tun.","fa":"تازه به یک خانه‌ی جدید اسباب‌کشی کرده‌ای و حتماً کار زیادی داری."},{"de":"In diesem Video erkläre ich dir, wie du dich beim Bürgeramt anmeldest.","fa":"در این ویدئو برایت توضیح می‌دهم که چطور در اداره‌ی امور شهروندی ثبت‌نام کنی."},{"de":"In Deutschland musst du deine neue Adresse innerhalb von zwei Wochen nach dem Umzug melden.","fa":"در آلمان باید آدرس جدیدت را ظرف دو هفته بعد از اسباب‌کشی اعلام کنی."},{"de":"Wenn du das nicht machst, musst du vielleicht eine Strafe bezahlen.","fa":"اگر این کار را نکنی، شاید مجبور شوی جریمه بپردازی."},{"de":"Zuerst brauchst du einen Termin, den du am besten online auf der Seite deiner Stadt buchst.","fa":"اول به یک وقت ملاقات نیاز داری که بهتر است آن را آنلاین در سایت شهرت رزرو کنی."},{"de":"Wegen der vielen Anfragen dauert es manchmal einige Tage, bis ein Termin frei ist.","fa":"به دلیل درخواست‌های زیاد، گاهی چند روز طول می‌کشد تا یک وقت خالی پیدا شود."},{"de":"Für die Anmeldung brauchst du drei Dokumente.","fa":"برای ثبت‌نام به سه مدرک نیاز داری."},{"de":"Erstens brauchst du deinen Pass oder deinen Personalausweis.","fa":"اول، به گذرنامه یا کارت شناسایی‌ات نیاز داری."},{"de":"Zweitens brauchst du das Anmeldeformular, das du schon zu Hause ausfüllen kannst.","fa":"دوم، به فرم ثبت‌نام نیاز داری که می‌توانی از قبل در خانه پرش کنی."},{"de":"Und drittens brauchst du eine Bestätigung deines Vermieters, die sogenannte Wohnungsgeberbestätigung.","fa":"و سوم، به تأییدیه‌ی صاحب‌خانه‌ات نیاز داری که به آن «تأییدیه‌ی واگذارکننده‌ی مسکن» می‌گویند."},{"de":"Vergiss nicht, alle Felder des Formulars vollständig auszufüllen und es zu unterschreiben.","fa":"فراموش نکن که همه‌ی خانه‌های فرم را کامل پر کنی و آن را امضا کنی."},{"de":"Während des Termins prüft ein Mitarbeiter deine Dokumente und gibt deine Daten in den Computer ein.","fa":"در طول وقت ملاقات، یک کارمند مدارکت را بررسی می‌کند و اطلاعاتت را در کامپیوتر وارد می‌کند."},{"de":"Das dauert normalerweise nur zehn bis fünfzehn Minuten.","fa":"این کار معمولاً فقط ده تا پانزده دقیقه طول می‌کشد."},{"de":"Am Ende bekommst du eine Meldebescheinigung, die du gut aufbewahren solltest.","fa":"در پایان یک گواهی ثبت آدرس می‌گیری که باید آن را خوب نگه داری."},{"de":"Diese brauchst du zum Beispiel, wenn du ein Konto bei einer Bank eröffnest.","fa":"مثلاً وقتی در یک بانک حساب باز می‌کنی، به آن نیاز داری."},{"de":"Die Anmeldung selbst ist übrigens gratis, du musst also nichts bezahlen.","fa":"راستی خود ثبت‌نام رایگان است، پس لازم نیست چیزی بپردازی."},{"de":"Wenn dir das Video geholfen hat, schau dir auch unser nächstes Video zum Thema Steuern an.","fa":"اگر این ویدئو به تو کمک کرد، ویدئوی بعدی ما درباره‌ی مالیات را هم تماشا کن."}],"q":[{"q":"Bis wann muss man die neue Adresse melden?","opts":["innerhalb von einem Monat","innerhalb von einer Woche","innerhalb von zwei Wochen"],"a":2,"fa":"در ویدئو آمده که باید آدرس جدید را ظرف دو هفته بعد از اسباب‌کشی اعلام کرد."},{"q":"Wie bucht man am besten einen Termin?","opts":["telefonisch","online auf der Seite der Stadt","persönlich im Amt"],"a":1,"fa":"گوینده می‌گوید بهتر است وقت را آنلاین در سایت شهر رزرو کنی."},{"q":"Welches Dokument bekommt man vom Vermieter?","opts":["den Personalausweis","das Anmeldeformular","die Wohnungsgeberbestätigung"],"a":2,"fa":"مدرک سوم تأییدیه‌ی صاحب‌خانه است که «Wohnungsgeberbestätigung» نام دارد."},{"q":"Wie lange dauert der Termin normalerweise?","opts":["etwa eine Stunde","einige Tage","zehn bis fünfzehn Minuten"],"a":2,"fa":"بررسی مدارک معمولاً ده تا پانزده دقیقه طول می‌کشد؛ «چند روز» مربوط به انتظار برای وقت خالی است."},{"q":"Wofür braucht man die Meldebescheinigung zum Beispiel?","opts":["für ein Zugticket","für ein Bankkonto","für einen Arzttermin"],"a":1,"fa":"در متن آمده که برای باز کردن حساب بانکی به آن نیاز داری."},{"q":"Was kostet die Anmeldung?","opts":["zehn Euro","fünf Euro","nichts"],"a":2,"fa":"گوینده می‌گوید خود ثبت‌نام رایگان است."}]}],"9":[{"id":"h1","type":"Nachrichten","title":"Das Wetter am Wochenende","title_fa":"هوای آخر هفته","intro_fa":"در پایان اخبار رادیو، گوینده پیش‌بینی هوای آخر هفته را برای مناطق مختلف آلمان اعلام می‌کند.","s":[{"de":"Und nun zum Wetter für das kommende Wochenende.","fa":"و حالا برویم سراغ هوای آخر هفته‌ی پیش رو."},{"de":"Nach den heißen und trockenen Tagen der letzten Woche wird es jetzt deutlich kühler.","fa":"بعد از روزهای گرم و خشک هفته‌ی گذشته، حالا هوا به‌طور محسوسی خنک‌تر می‌شود."},{"de":"Am Freitag ist es im Norden zwar noch sonnig, aber am Nachmittag ziehen von Westen dunkle Wolken auf.","fa":"روز جمعه در شمال هوا هنوز آفتابی است، اما بعدازظهر ابرهای تیره از غرب می‌آیند."},{"de":"Am Abend kommt es sowohl in Bayern als auch in Baden-Württemberg zu starken Gewittern.","fa":"عصر هم در بایرن و هم در بادن‌وورتمبرگ رعدوبرق‌های شدید رخ می‌دهد."},{"de":"Dabei kann es nicht nur heftig regnen, sondern auch hageln.","fa":"در این میان نه‌تنها ممکن است باران شدید ببارد، بلکه تگرگ هم ببارد."},{"de":"Bitte bleiben Sie bei Blitz und Donner nicht im Freien und stellen Sie sich nicht unter hohe Bäume.","fa":"لطفاً هنگام برق و رعد در فضای باز نمانید و زیر درختان بلند نایستید."},{"de":"Die Bauern freuen sich trotzdem auf den Regen, weil die Felder nach vielen Wochen ohne Regen sehr trocken sind.","fa":"با این حال کشاورزان از باران خوشحال‌اند، چون مزرعه‌ها بعد از چند هفته بی‌بارانی خیلی خشک هستند."},{"de":"Viele haben Angst, dass die Ernte in diesem Jahr kleiner wird als sonst.","fa":"بسیاری نگران‌اند که محصول امسال کمتر از سال‌های دیگر باشد."},{"de":"Am Samstag ist es überall feucht und kühl bei Temperaturen zwischen 14 und 18 Grad.","fa":"روز شنبه همه‌جا هوا مرطوب و خنک است، با دمای بین ۱۴ تا ۱۸ درجه."},{"de":"An der Küste weht ein starker Wind, deshalb sollten Segler entweder im Hafen bleiben oder sehr vorsichtig sein.","fa":"در ساحل باد شدیدی می‌وزد، به همین دلیل قایقرانان یا باید در بندر بمانند یا خیلی مراقب باشند."},{"de":"Im Gebirge fällt oberhalb von 2000 Metern sogar der erste Schnee.","fa":"در کوهستان بالای ۲۰۰۰ متر حتی اولین برف هم می‌بارد."},{"de":"Wanderer sollten deshalb weder zu leichte Kleidung tragen noch ohne Regenjacke losgehen.","fa":"بنابراین کوه‌نوردان نه باید لباس خیلی نازک بپوشند و نه بدون بارانی راه بیفتند."},{"de":"Die Wege können nass und glatt sein, besonders an steilen Stellen.","fa":"مسیرها ممکن است خیس و لغزنده باشند، به‌خصوص در جاهای شیب‌دار."},{"de":"Am Sonntag wird es dann wieder freundlicher.","fa":"یکشنبه دوباره هوا بهتر می‌شود."},{"de":"Im Süden scheint schon am Vormittag die Sonne, im Norden bleibt es noch bewölkt.","fa":"در جنوب از همان صبح آفتاب می‌تابد، اما در شمال هوا هنوز ابری می‌ماند."},{"de":"Nachts kann es in den Tälern bis auf fünf Grad abkühlen, man friert also schnell.","fa":"شب‌ها در دره‌ها دما ممکن است تا پنج درجه پایین بیاید، پس آدم زود سردش می‌شود."},{"de":"Ab Montag erwarten wir wieder sommerliche Temperaturen um 25 Grad.","fa":"از دوشنبه دوباره دماهای تابستانی حدود ۲۵ درجه را انتظار داریم."}],"q":[{"q":"Wo gibt es am Freitagabend starke Gewitter?","opts":["an der Küste","in Bayern und Baden-Württemberg","im ganzen Norden"],"a":1,"fa":"گوینده می‌گوید عصر جمعه «هم در بایرن و هم در بادن‌وورتمبرگ» رعدوبرق شدید رخ می‌دهد."},{"q":"Warum freuen sich die Bauern auf den Regen?","opts":["Weil sie früher ernten wollen.","Weil die Felder sehr trocken sind.","Weil es für die Tiere zu kalt ist."],"a":1,"fa":"مزرعه‌ها بعد از چند هفته بی‌بارانی خیلی خشک هستند."},{"q":"Was sollen Segler am Samstag tun?","opts":["in die Berge fahren","weit aufs Meer fahren","im Hafen bleiben oder sehr vorsichtig sein"],"a":2,"fa":"به دلیل باد شدید، قایقرانان یا باید در بندر بمانند یا خیلی مراقب باشند."},{"q":"Was passiert im Gebirge?","opts":["Über 2000 Metern fällt der erste Schnee.","Es wird sehr heiß.","Es gibt keinen Regen."],"a":0,"fa":"در متن آمده که بالای ۲۰۰۰ متر اولین برف می‌بارد."},{"q":"Wie ist das Wetter am Sonntag im Süden?","opts":["bewölkt","stürmisch","sonnig"],"a":2,"fa":"یکشنبه در جنوب از صبح آفتاب است؛ ابری بودن مربوط به شمال است."},{"q":"Welche Temperaturen erwartet man ab Montag?","opts":["um 25 Grad","zwischen 14 und 18 Grad","um fünf Grad"],"a":0,"fa":"از دوشنبه دماهای تابستانی حدود ۲۵ درجه پیش‌بینی می‌شود."}]},{"id":"h2","type":"Führung","title":"Zu Besuch auf dem Sonnenhof","title_fa":"بازدید از مزرعه‌ی زونن‌هوف","intro_fa":"یک کشاورز گروهی از بازدیدکنندگان را در مزرعه‌ی خانوادگی‌اش می‌گرداند و درباره‌ی حیوانات، کشاورزی ارگانیک و انرژی خورشیدی توضیح می‌دهد.","s":[{"de":"Hallo zusammen und herzlich willkommen auf dem Sonnenhof!","fa":"سلام به همه، به مزرعه‌ی زونن‌هوف خیلی خوش آمدید!"},{"de":"Ich bin Martin Huber, und ich zeige euch heute unseren Bauernhof.","fa":"من مارتین هوبر هستم و امروز مزرعه‌مان را به شما نشان می‌دهم."},{"de":"Unser Hof liegt in einem ruhigen Tal, umgeben von grünen Wiesen und kleinen Hügeln.","fa":"مزرعه‌ی ما در یک دره‌ی آرام قرار دارد و دورش را چمنزارهای سبز و تپه‌های کوچک گرفته‌اند."},{"de":"Meine Familie betreibt hier schon seit 1920 Landwirtschaft.","fa":"خانواده‌ی من از سال ۱۹۲۰ اینجا کشاورزی می‌کند."},{"de":"Heute haben wir sowohl Kühe und Schweine als auch Hühner und zwei Pferde.","fa":"امروز هم گاو و خوک داریم و هم مرغ و دو اسب."},{"de":"Seit fünf Jahren arbeiten wir ökologisch, das heißt, wir benutzen weder Chemie auf den Feldern noch künstliches Futter für die Tiere.","fa":"از پنج سال پیش به‌صورت ارگانیک کار می‌کنیم، یعنی نه در مزرعه‌ها مواد شیمیایی به کار می‌بریم و نه برای حیوانات خوراک مصنوعی."},{"de":"Die Kühe fressen im Sommer frisches Gras auf der Wiese und im Winter Heu.","fa":"گاوها در تابستان علف تازه در چمنزار می‌خورند و در زمستان یونجه‌ی خشک."},{"de":"Jeden Morgen um sechs Uhr lassen wir sie in den Stall kommen, und dann werden sie gemolken.","fa":"هر روز صبح ساعت شش آن‌ها را به طویله می‌آوریم و بعد دوشیده می‌شوند."},{"de":"Gleich dürft ihr die Kaninchen und die Ziegen füttern, aber bitte nur mit dem Futter aus diesem Eimer.","fa":"الان می‌توانید به خرگوش‌ها و بزها غذا بدهید، اما لطفاً فقط با غذای داخل این سطل."},{"de":"Die Ziegen sind zwar sehr freundlich, aber manchmal beißen sie ein bisschen in die Finger.","fa":"بزها البته خیلی مهربان‌اند، اما گاهی کمی انگشت آدم را گاز می‌گیرند."},{"de":"Hinter dem Stall seht ihr unsere Solaranlage auf dem Dach der Scheune.","fa":"پشت طویله، سیستم خورشیدی ما را روی سقف انبار می‌بینید."},{"de":"Die haben wir letztes Jahr bauen lassen, weil wir nicht nur Geld sparen, sondern auch die Umwelt schützen wollen.","fa":"آن را پارسال دادیم بسازند، چون می‌خواهیم نه‌تنها پول صرفه‌جویی کنیم، بلکه از محیط زیست هم محافظت کنیم."},{"de":"Mit dem Strom laden wir zum Beispiel unseren elektrischen Traktor.","fa":"مثلاً با این برق تراکتور برقی‌مان را شارژ می‌کنیم."},{"de":"Auf dem großen Feld dort drüben wachsen Kartoffeln, und im September beginnt die Ernte.","fa":"در آن مزرعه‌ی بزرگ آن طرف سیب‌زمینی می‌روید و برداشت در سپتامبر شروع می‌شود."},{"de":"Wer möchte, kann dann wiederkommen und uns beim Ernten helfen.","fa":"هر کس بخواهد، می‌تواند آن موقع دوباره بیاید و در برداشت به ما کمک کند."},{"de":"Zum Schluss könnt ihr in unserem Hofladen Milch, Käse und Eier kaufen.","fa":"در آخر می‌توانید از فروشگاه مزرعه‌مان شیر، پنیر و تخم‌مرغ بخرید."},{"de":"Jetzt gehen wir aber erst einmal zu den Tieren!","fa":"اما حالا اول برویم پیش حیوانات!"}],"q":[{"q":"Seit wann betreibt die Familie Huber Landwirtschaft?","opts":["seit 1920","seit fünf Jahren","seit letztem Jahr"],"a":0,"fa":"کشاورز می‌گوید خانواده‌اش از سال ۱۹۲۰ آنجا کشاورزی می‌کند؛ پنج سال مربوط به کار ارگانیک است."},{"q":"Was bedeutet „ökologisch“ auf diesem Hof?","opts":["Sie benutzen weder Chemie noch künstliches Futter.","Sie haben mehr Tiere als früher.","Sie haben nur Pflanzen und keine Tiere."],"a":0,"fa":"او توضیح می‌دهد: «نه مواد شیمیایی در مزرعه‌ها و نه خوراک مصنوعی برای حیوانات»."},{"q":"Was fressen die Kühe im Sommer?","opts":["Heu","Kartoffeln","frisches Gras"],"a":2,"fa":"گاوها در تابستان علف تازه می‌خورند و در زمستان یونجه."},{"q":"Warum sollen die Besucher bei den Ziegen aufpassen?","opts":["Sie laufen schnell weg.","Sie sind krank.","Sie beißen manchmal in die Finger."],"a":2,"fa":"بزها مهربان‌اند، اما گاهی انگشت آدم را گاز می‌گیرند."},{"q":"Warum hat die Familie die Solaranlage bauen lassen?","opts":["um Strom an die Nachbarn zu verkaufen","weil die Stadt es verlangt hat","um Geld zu sparen und die Umwelt zu schützen"],"a":2,"fa":"در متن آمده: «نه‌تنها برای صرفه‌جویی در پول، بلکه برای محافظت از محیط زیست»."},{"q":"Wann beginnt die Kartoffelernte?","opts":["im Juli","im September","im November"],"a":1,"fa":"کشاورز می‌گوید برداشت سیب‌زمینی در سپتامبر شروع می‌شود."}]}]};
